COLLDATA("tadabburar","ar",[[197,"§التوبة\nwords\nيُحَادِدِيُشَاقِّ وَيُخَالِف.\nحَسبُهُمكَافِيهِم.\ndeeds\nاحرص اليوم -وبأسلوب حسن- على الأمر بالمعروف والنهي عن المنكر، مخالفًا حال المنافقين.\nتصدق بصدقة حسب استطاعتك، ثم داوم على ذلك، وتذكر أن أهل النفاق يقبضون أيديهم.\nأكثر اليوم من ذكر الله تعالى لتتبرأ من النفاق؛ فإن المنافق ينسى الله تعالى ولا يذكره إلا قليلًا.\nguid\nالمؤمن يراقب الله، والمنافق يراقب الناس؛ وكلٌّ يسعى لإرضاء من يراقبه.\nالاستهزاء بشعائر الإسلام وبالمنتسبين إليه قد يُورد صاحبه نار جهنم، حتى ولو كان من باب الضحك والتسلية.\nللمنافقين صفات ظاهرة تميزهم عن المؤمنين.\nrefl\nوَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرۡضُوهُ إِن كَانُواْ مُؤۡمِنِينَ ٦٢\nلأن المؤمن لا يقدم شيئًا على رضا ربه ورضا رسوله؛ فدل هذا على انتفاء إيمانهم، حيث قدّموا رضا غير الله ورسوله، وهذا محادة لله ومشاقة له. السعدي:٣٤٢.\nمن علامات المنهج الصحيح تقديم رضا الله سبحانه على رضا غيره، وضح ذلك.\nيَحۡذَرُ ٱلۡمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيۡهِمۡ سُورَةٞ تُنَبِّئُهُم بِمَا فِي قُلُوبِهِمۡۚ قُلِ ٱسۡتَهۡزِءُوٓاْ إِنَّ ٱللَّهَ مُخۡرِجٞ مَّا تَحۡذَرُونَ ٦٤\nقال قتادة: \"كانت تسمى هذه السورة (الفاضحة)؛ فاضحة المنافقين\". ابن كثير:٢/٣٥١.\nمع كل حادثة يحسن تدبر سورة معينة، فمتى يحسن تكرار تدبر سورة التوبة؟\nيَحۡذَرُ ٱلۡمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيۡهِمۡ سُورَةٞ تُنَبِّئُهُم بِمَا فِي قُلُوبِهِمۡۚ قُلِ ٱسۡتَهۡزِءُوٓاْ إِنَّ ٱللَّهَ مُخۡرِجٞ مَّا تَحۡذَرُونَ ٦٤\nوفي هذه الآيات دليلٌ على أن من أَسَرَّ سريرة -خصوصًا السريرة التي يمكر فيها بدينه، ويستهزئ به وبآياته ورسوله- أن الله تعالى يظهرها، ويفضح صاحبها، ويعاقبه أشد العقوبة. السعدي:٣٤٣.\nتكثر الفضائح الأخلاقية على قساوسة النصارى وأئمة الشيعة؛ فما السر في ذلك؟\nوَلَئِن سَأَلۡتَهُمۡ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلۡعَبُۚ قُلۡ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ ٦٥ لَا تَعۡتَذِرُواْ قَدۡ كَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡۚ\nالاستهزاء بالله وآياته ورسوله كفر مخرج عن الدين؛ لأن أصل الدين مبني على تعظيم الله، وتعظيم دينه ورسله؛ والاستهزاء بشيء من ذلك منافٍ لهذا الأصل، ومناقض له أشد المناقضة. السعدي:٣٤٣.\nلماذا كان الاستهزاء بالله وآياته ورسوله كفرًا مخرجًا عن الدين؟\nوَلَئِن سَأَلۡتَهُمۡ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلۡعَبُۚ قُلۡ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ ٦٥ لَا تَعۡتَذِرُواْ قَدۡ كَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡۚ\nدلت هذه الآية على أن كل من تَنقَّص رسول الله -صلى الله عليه و سلم- جادًّا أو هازلًا؛ فقد كفر. ابن تيمية:٣/٤٠٠.\nما حكم تنقُّص النبي -صلى الله عليه وسلم- واحتقاره؟\nقُلۡ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ ٦٥ لَا تَعۡتَذِرُواْ قَدۡ كَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡۚ\nنُقل عن الشافعي أنه سئل عمن هزل بشيء من آيات الله تعالى أنه قال: هو كافر، و استدل بقول الله تعالى: (قل أبالله وآياته ورسوله كنتم تستهزئون * لا تعتذروا قد كفرتم بعد إيمانكم). ابن تيمية:٣/٤٠٢.\nما حكم من هزل بشيء من آيات الله تعالى؟\nنَسُواْ ٱللَّهَ فَنَسِيَهُمۡۚ\nتركوا طاعة الله؛ فتركهم الله من توفيقه وهدايته في الدنيا، ومن رحمته في الآخرة، وتركهم في عذابه. البغوي:٢/٣٠٢.\nالجزاء من جنس العمل، بيِّن ذلك من خلال الآية."],[198,"§التوبة\nwords\nفَاستَمتَعُوا بِخَلاَقِهِمفَتَمَتَّعُوا بِنَصِيبِهِم مِن مَلاَذِّ الدُّنيَا.\nوَخُضتُمدَخَلتُم فِي الكَذِبِ وَالبَاطِلِ.\nحَبِطَتبَطَلَت.\nوَالمُؤتَفِكَاتِقُرَى قَومِ لُوطٍ، سُمِّيَت بِذَلِكَ؛ لأِنَّ اللهَ قَلَبَهَا عَلَيهِم.\ndeeds\nاحرص اليوم على الصحبة الصالحة حتى تحقق عبادة الموالاة، والمؤاخاة الإيمانية التي دعانا ربنا إليها، ولتكن رفقتك الدائمة.\nأرسل رسائل تأمر فيها بالمعروف؛ كعبادة قصَّر فيها الناس، أو تنهى فيها عن منكر؛ كمعصية تساهل فيها الناس.\nسل الله تعالى أن يرضى عنك في الدارين.\nguid\nالنجاة في الحياة الدنيا وفي الآخرة إنَّما هي باتباع ما جاءت به الرسل.\nاقرأ في قصص الأنبياء حتى تكون من الذين يعتبرون ويتعظون إذا تليت عليهم أنباء الرسل وأممهم.\nالأمر بالمعروف والنهي عن المنكر من أبرز الصفات التي تميز بين المؤمنين والمنافقين.\nrefl\nكَٱلَّذِينَ مِن قَبۡلِكُمۡ كَانُوٓاْ أَشَدَّ مِنكُمۡ قُوَّةٗ وَأَكۡثَرَ أَمۡوَٰلٗا وَأَوۡلَٰدٗا فَٱسۡتَمۡتَعُواْ بِخَلَٰقِهِمۡ فَٱسۡتَمۡتَعۡتُم بِخَلَٰقِكُمۡ كَمَا ٱسۡتَمۡتَعَ ٱلَّذِينَ مِن قَبۡلِكُم بِخَلَٰقِهِمۡ وَخُضۡتُمۡ كَٱلَّذِي خَاضُوٓاْۚ أُوْلَٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ٦٩\nفما صَدَّ أكثرَ هذه الأمة عن فهم القرآن: ظنُّهم أنَّ الذي فيه مِن قَصَص الأوَّلِين وأخبار المُثَابين والمُعَاقَبين مِن أهل الأديان أجمعين؛ أنَّ ذلك إنَّما مقصوده الإخبار والقَصص فقط. كلا، وليس كذلك؛ إنَّما مقصودُهُ الاعتبار، والتنبيه لمشاهدة متكررة في هذه الأمة من نظائر جميع أولئك الأعداد وتلك الأحوال والآثار. البقاعي:٣/٣٤٧.\nما المقصود من قَصص القرآن وأخباره التي نقرؤها فيه؟\nفَٱسۡتَمۡتَعۡتُم بِخَلَٰقِكُمۡ كَمَا ٱسۡتَمۡتَعَ ٱلَّذِينَ مِن قَبۡلِكُم بِخَلَٰقِهِمۡ\nوأما المؤمنون؛ فهم وإن استمتعوا بنصيبهم وما خُولوا من الدنيا فإنه على وجه الاستعانة به على طاعة الله، وأمَّا علومهم؛ فهي علوم الرسل، وهي الوصول إلى اليقين في جميع المطالب العالية، والمجادلة بالحق لإدحاض الباطل. السعدي:٣٤٣.\nما الفرق بين تمتُّع المؤمنين وتمتُّع المنافقين والكافرين بمتاع الحياة الدنيا؟\nفَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ٧٠\nأي: بالكفر والتكذيب، وترك شكره تعالى، وصرفهم نعمه إلى غير ما أعطاهم إياها لأجله؛ فاستحقوا ذلك العذاب. القاسمي:٤/١٦٦.\nما مظاهر ظلم النفس، واستحقاق العذاب النازل على المكذبين؟\nوَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ\nوعبّر في جانب المؤمنين والمؤمنات بأنّهم أولياء بعض للإشارة إلى أنّ اللحمة الجامعة بينهم هي وَلاية الإسلام؛ فهم فيها على السواء، ليس واحد منهم مقلّدًا للآخر، ولا تابعًا له على غير بصيرة؛ لما في معنى الولاية من الإشعار بالإخلاص والتناصر، بخلاف المنافقين؛ فكأنّ بَعضَهم ناشئ من بعض في مذامّهم. ابن عاشور:١٠/٢٦٢.\nلم عبرت الآية الكريمة في جانب المؤمنين بأنهم أولياء بعض؟\nوَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ\nأي: قلوبهم متحدة في التواد، والتحاب، والتعاطف. القرطبي:١٠/٢٩٨.\nبيّن كيف يكون قلب المؤمن الحق تجاه أخيه المؤمن.\nأُوْلَٰٓئِكَ سَيَرۡحَمُهُمُ ٱللَّهُۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ ٧١\nوجملة: ﴿أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ﴾ تعليل لجملة ﴿سَيَرۡحَمُهُمُ ٱللَّهُۗ﴾ أي: أنّه تعالى لعزّته ينفع أولياءه، وأنّه لحكمته يضع الجزاء لمستحقّه. ابن عاشور:١٠/٢٦٣.\nما مناسبة ختام الآية الكريمة باسمي الله تعالى: ﴿عَزِيزٌ حَكِيمٌ﴾؟\nوَرِضۡوَٰنٞ مِّنَ ٱللَّهِ أَكۡبَرُۚ\nورضوان من الله يحله على أهل الجنة، أكبر مما هم فيه من النعيم؛ فإن نعيمهم لم يطب إلا برؤية ربهم ورضوانه عليهم، ولأنه الغاية التي أمَّها العابدون، والنهاية التي سعى نحوها المحبون؛ فرضى رب الأرض والسماوات أكبر من نعيم الجنات. السعدي:٣٤٤.\nلم وصف رضوان الله بأنه أكبر من نعيم الجنان؟"],[199,"§التوبة\nwords\nنَقَمُواكَرِهُوا، وَعَابُوا.\nفَأَعقَبَهُمفَصَيَّرَ عَاقِبَتَهُم وَجَزَاءَهُم.\nيَلمِزُونَيَعِيبُونَ.\nالمُطَّوِّعِينَالَّذِينَ يَتَطَوَّعُونَ بِالصَّدَقَةِ بِالمَالِ الكَثِيرِ.\ndeeds\nساهم اليوم في مجاهدة الكفار والمنافقين ولو بكلمات في مجالسك أو على صفحات النت، أو رسائل الهاتف الجوال.\nلخِّص صفات المنافقين الموجودة في هذا الوجه.\nأدِّ عبادة في السر لا يطلع عليها سوى الله تعالى.\nguid\nكثرة الحلف مذمومة؛ لأنها مظنة الكذب، ويلجأ إليها المنافقون، أما المؤمن؛ فيعظم الله تعالى، ولا يتساهل بالحلف.\nمرض القلب وإصابته بالنفاق عقوبة إلهية لمن ترك السبيل المستقيم.\nلا تخجل من العمل القليل في سبيل الله؛ فالعبرة بالدافع القلبي للعمل وليس بكمية العمل.\nrefl\nيَٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ ٧٣\nجهاد الكفار بالسيف، وجهاد المنافقين باللسان ما لم يظهر ما يدل على كفرهم. ابن جزي:١/٣٦٤.\nكيف يكون جهاد الكفار وجهاد المنافقين؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ\nأمر تعالى رسوله -صلى الله عليه وسلم- بجهاد الكفار والمنافقين، والغلظة عليهم، كما أمره بأن يخفض جناحه لمن اتبعه من المؤمنين. ابن كثير:٢/٣٥٥.\nما الفرق بين تعامل المسلم مع المسلم، وتعامله مع الكافر والمنافق؟\nيَٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ\nوهذا الجهاد يدخل فيه: الجهاد باليد، والجهاد بالحجة واللسان. فمن بارز منهم بالمحاربة؛ فيُجاهد باليد واللسان، والسيف والبيان. ومن كان مذعنًا للإسلام بذمة أو عهد؛ فإنه يجاهد بالحجة والبرهان، ويبين له محاسن الإسلام، ومساوئ الشرك والكفر. السعدي:٣٤٤.\nما مراتب جهاد الكفار والمنافقين؟\nيَحۡلِفُونَ بِٱللَّهِ مَا قَالُواْ وَلَقَدۡ قَالُواْ كَلِمَةَ ٱلۡكُفۡرِ وَكَفَرُواْ بَعۡدَ إِسۡلَٰمِهِمۡ\nلم يقل بعد إيمانهم؛ لأنهم كانوا يقولون بألسنتهم آمنا ولم يدخل الإيمان في قلوبهم. ابن جزي:١/٣٦٤.\nما وجه التعبير بــ (إسلامهم) دون \"إيمانهم\" في الآية ؟\nوَمِنۡهُم مَّنۡ عَٰهَدَ ٱللَّهَ لَئِنۡ ءَاتَىٰنَا مِن فَضۡلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّٰلِحِينَ ٧٥ فَلَمَّآ ءَاتَىٰهُم مِّن فَضۡلِهِۦ بَخِلُواْ بِهِۦ وَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ ٧٦ فَأَعۡقَبَهُمۡ نِفَاقٗا فِي قُلُوبِهِمۡ إِلَىٰ يَوۡمِ يَلۡقَوۡنَهُۥ بِمَآ أَخۡلَفُواْ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُواْ يَكۡذِبُونَ ٧٧\nفليحذر المؤمن من هذا الوصف الشنيع؛ أن يعاهد ربه: إن حصل مقصوده الفلاني ليفعلنَّ كذا وكذا، ثم لا يفي بذلك؛ فإنه ربما عاقبه الله بالنفاق كما عاقب هؤلاء. السعدي:٣٤٥.\nبيٍّن خطورة إخلاف الوعد مع الله سبحانه، وشدة عقوبته.\nفَأَعۡقَبَهُمۡ نِفَاقٗا فِي قُلُوبِهِمۡ إِلَىٰ يَوۡمِ يَلۡقَوۡنَهُۥ بِمَآ أَخۡلَفُواْ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُواْ يَكۡذِبُونَ ٧٧\nوعبّر عن كذبهم بصيغة ﴿كَانُواْ يَكۡذِبُونَ﴾ لدلالة كان على أنّ الكذب كائن فيهم ومتمكّن منهم، ودلالة المضارع على تكرّره وتجدّده. ابن عاشور:١٠/٢٧٣.\nلماذا عبرت الآية الكريمة عن كذب المنافقين بـــــ ﴿كَانُواْ يَكۡذِبُونَ﴾؟\nٱلَّذِينَ يَلۡمِزُونَ ٱلۡمُطَّوِّعِينَ مِنَ ٱلۡمُؤۡمِنِينَ فِي ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهۡدَهُمۡ فَيَسۡخَرُونَ مِنۡهُمۡ سَخِرَ ٱللَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ ٧٩\nمن أطاع الله وتطوّع بخصلة من خصال الخير؛ فإن الذي ينبغي هو: إعانته، وتنشيطه على عمله، وهؤلاء قصدوا تثبيطهم بما قالوا فيهم، وعابوهم فيه. السعدي:٣٤٦.\nما الذي يجب على المؤمنين إذا رأوا أحدًا يعمل بخصلة من خصال الخير؟ وكيف يفاد هذا من الآية؟"],[200,"§التوبة\nwords\nبِمَقعَدِهِمبِقُعُودِهِم.\nخِلاَفَمُخَالِفِينَ.\nالخَالِفِينَالمُتَخَلِّفِينَ عَنِ الجِهَادِ.\nأُولُو الطَّولِأَصحَابُ الغِنَى وَالسَّعَةِ.\ndeeds\nقارن بين عدد ضحكاتك وبكائك من خشية الله خلال الشهر الماضي.\nحافظ على صلاة الجماعة في شدة الحر وشدة البرد، ولا تتخلف عنها.\nأدِّ عملًا تجاهد فيه نفسك، وتضحي براحتك ونشاطك؛ كصيام يوم شديد الحر، أو الخروج في حاجة مسكين أو مضطر؛ لعل الله أن يفرج كربك.\nguid\nمن علامات مرض القلب: كراهية الطاعات والعبادات.\nالنهي عن الإعجاب بأحوال الكافرين المادية.\nكثرة الاستئذان عن العبادة بدون عذر صادق وحقيقي أمر مذموم.\nrefl\nفَرِحَ ٱلۡمُخَلَّفُونَ بِمَقۡعَدِهِمۡ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓاْ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ\nوهذا قدر زائد على مجرد التخلف؛ فإن هذا تخلف محرم، وزيادة رضا بفعل المعصية، وتبجح به. ﴿وَكَرِهُوٓاْ أَن يُجَٰهِدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ﴾: وهذا بخلاف المؤمنين الذين إذا تخلفوا -ولو لعذر- حزنوا على تخلفهم، وتأسفوا غاية الأسف، ويحبون أن يجاهدوا بأموالهم وأنفسهم في سبيل الله؛ لما في قلوبهم من الإيمان، ولما يرجون من فضل الله وإحسانه وبره وامتنانه. السعدي:٣٤٦.\nما الفرق بين المؤمن والمنافق إذا فاتتهم الأعمال الصالحة؟\nفَرِحَ ٱلۡمُخَلَّفُونَ بِمَقۡعَدِهِمۡ خِلَٰفَ رَسُولِ ٱللَّهِ\nهذه آية تتضمن وصف حالهم على جهة التوبيخ لهم، وفي ضمنها وعيد. وقوله: (المُخَلَّفُونَ) لفظ يقتضي تحقيرهم وأنهم الذين أبعدهم الله من رضاه، وهذا أمكن في هذا من أن يقال: \"المتخلفون\". ولم يفرح إلا منافق؛ فخرج من ذلك: الثلاثة، وأصحاب العذر. ابن عطية: ٣/٦٥.\nلماذا قال تعالى: (المخلفون) ولم يقل: \"المتخلفون\"؟ وماذا نستفيد من ذلك؟\nوَقَالُواْ لَا تَنفِرُواْ فِي ٱلۡحَرِّۗ قُلۡ نَارُ جَهَنَّمَ أَشَدُّ حَرّٗاۚ لَّوۡ كَانُواْ يَفۡقَهُونَ ٨١\nفقدَّموا راحة قصيرة منقضية على الراحة الأبدية التامة، وحذروا من الحر الذي يقي منه الظلال ويذهبه البكر والآصال، على الحر الشديد الذي لا يقادر قدره؛ وهو النار الحامية. السعدي:٣٤٦.\nما سبب وصف الله المنافقين بعدم الفقه؟\nفَلۡيَضۡحَكُواْ قَلِيلٗا وَلۡيَبۡكُواْ كَثِيرٗا جَزَآءَۢ بِمَا كَانُواْ يَكۡسِبُونَ ٨٢\nكان الصحابة يضحكون، إلا أن الإكثار منه وملازمته حتى يغلب على صاحبه مذموم منهي عنه، وهو من فعل السفهاء والبطالة، وفي الخبر أن كثرته تميت القلب. القرطبي:١٠/٣١٨.\nبيّن كيف يكون حال المؤمن مع الضحك؟\nإِنَّكُمۡ رَضِيتُم بِٱلۡقُعُودِ أَوَّلَ مَرَّةٖ فَٱقۡعُدُواْ مَعَ ٱلۡخَٰلِفِينَ ٨٣\nفإن المتثاقل المتخلف عن المأمور به عند انتهاز الفرصة لا يوفق له بعد ذلك، ويحال بينه وبينه. السعدي:٣٤٦.\nما خطورة ترك العبادات والأعمال الصالحة في حال تهيؤ الظروف المناسبة؟\nوَلَا تُصَلِّ عَلَىٰٓ أَحَدٖ مِّنۡهُم مَّاتَ أَبَدٗا وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦٓۖ إِنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُواْ وَهُمۡ فَٰسِقُونَ ٨٤\nوالسنة في زيارة قبور المسلمين نظير الصلاة عليهم قبل الدفن؛ قال الله تعالى في كتابه عن المنافقين: ﴿وَلَا تُصَلِّ عَلَىٰٓ أَحَدٍ مِّنۡهُم مَّاتَ أَبَدًا وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦٓۖ﴾ فكان دليل الخطاب أن المؤمنين يُصلَّى عليهم. ابن تيمية:٣/٤٣٥.\nما حكم الدعاء للمؤمنين عند قبورهم؟\nوَلَا تُعۡجِبۡكَ أَمۡوَٰلُهُمۡ وَأَوۡلَٰدُهُمۡۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِي ٱلدُّنۡيَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَٰفِرُونَ ٨٥\nتدريبًا لهم على الحبِّ في الله، والبُغض فيه؛ لأنه من أدقِّ أبواب الدِّين فهمًا، وأجلها قَدرًا، وعليه تُبتنى غالب أبوابه، ومنه تُجتنى أكثرُ ثمراته وآدابه؛ وذلك أنه ربما ظنَّ الناظر فيمن بُسِطت عليه الدنيا أنه من الناجين؛ فيوادُّه لحسن قوله، غافلًا عن سوء فعله. البقاعي:٣/٣٧١.\nكيف نفيد من هذه الآية في تطبيق الولاء والبراء في الله؟"],[201,"§التوبة\nwords\nالمُعَذِّرُونَالمُعتَذِرُونَ.\nنَصَحُوا لِلَّهِأَخلَصُوا للهِ، وَلَم يُثَبِّطُوا، وَعَلِمَ اللهُ مِن قُلُوبِهِم أَنَّهُم لَولاَ العُذرُ لَجَاهَدُوا.\ndeeds\nقل في دعائك: \"اللهم يا مقلب القلوب ثبت قلبي على دينك، اللهم أصلح لي قلبي\".\nاقرأ كتابًا، أو استمع إلى مقطع صوتي يرفع همتك للطاعة وعمل الخير؛ ككتب السنة النبوية وتراجم الأعلام؛ فالرضا بالدون والمعصية من شأن المنافقين، لا من صفات المؤمنين.\nأدِّ بعض الأعمال التي تصلح القلب وتحييه؛ كزيارة المقابر، ومساعدة محتاج أو مسكين، ونحوها.\nguid\nالمال الذي بين يديك إنَّما هو لاختبارك، فأنفقه حيث يحب الله ورسوله، ولو كان ذلك مكروهًا لنفسك.\nالصحابة بكوا لفوات الطاعة، مع أنهم معذورون بنص القرآن؛ فهل بكيت يومًا على فوات طاعة.\nلا تعتذر وأنت كاذب أو مخادع؛ فإن الله تعالى يعلم السر وأخفى.\nrefl\nرَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ\nفإذا وقع الحرب؛ كانوا أجبن الناس، وإذا كان أَمنٌ كانوا أكثر الناس كلامًا. ابن كثير:٢/٣٦٣\nما الفرق بين المؤمن والمنافق في حالتي السِّلم والحرب؟\nلَّيۡسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلۡمَرۡضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُواْ لِلَّهِ وَرَسُولِهِۦۚ\nقوله تعالى: ﴿إِذَا نَصَحُواْ لِلَّهِ وَرَسُولِهِۦۚ﴾ أي: أخلصوا لله ورسوله قصدهم وحبهم. ابن تيمية:٣/٤٣٧.\nما المراد بـــــــ﴿نَصَحُواْ لِلَّهِ وَرَسُولِهِۦۚ﴾ في الآية الكريمة؟\nلَّيۡسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلۡمَرۡضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُواْ لِلَّهِ وَرَسُولِهِۦۚ مَا عَلَى ٱلۡمُحۡسِنِينَ مِن سَبِيلٖۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ٩١\n﴿إِذَا نَصَحُواْ لِلَّهِ﴾ يعني: بنياتهم وأقوالهم، وإن لم يخرجوا للغزو، ﴿مَا عَلَى ٱلۡمُحۡسِنِينَ مِن سَبِيلٍۚ﴾: وصفهم بالمحسنين؛ لأنهم نصحوا لله ورسوله، ورفع عنهم العقوبة والتعنيف واللوم. ابن جزي:١/٣٦٧.\nما وجه وصف الضعفاء والمرضى والفقراء بالإحسان، مع أنهم لم يجاهدوا ولم يتصدقوا؟\nمَا عَلَى ٱلۡمُحۡسِنِينَ مِن سَبِيلٖۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ٩١\n﴿وَٱللَّهُ غَفُورٌ رَّحِيمٌ﴾ إشارة إلى أن الإنسان محل التقصير والعجز وإن اجتهد؛ فلا يسعه إلا العفو. البقاعي:٣/٣٧٤.\nما الحكمة في ختم الآية باسمي (الغفور) و(الرحيم)، مع أنها تتكلم عن المحسنين؟\nوَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوۡكَ لِتَحۡمِلَهُمۡ قُلۡتَ لَآ أَجِدُ مَآ أَحۡمِلُكُمۡ عَلَيۡهِ تَوَلَّواْ وَّأَعۡيُنُهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ حَزَنًا أَلَّا يَجِدُواْ مَا يُنفِقُونَ ٩٢\nفهؤلاء لا حرج عليهم، وإذا سقط الحرج عنهم عاد الأمر إلى أصله، وهو: أن من نوى الخير، واقترن بنيته الجازمة سعيٌ فيما يقدر عليه، ثم لم يقدر؛ فإنه يُنَزَّل منزلة الفاعل التام. السعدي:٣٤٨.\nما أهمية النية الصادقة؟ أجب من خلال هذه الآية.\nوَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوۡكَ لِتَحۡمِلَهُمۡ قُلۡتَ لَآ أَجِدُ مَآ أَحۡمِلُكُمۡ عَلَيۡهِ تَوَلَّواْ وَّأَعۡيُنُهُمۡ تَفِيضُ مِنَ ٱلدَّمۡعِ حَزَنًا أَلَّا يَجِدُواْ مَا يُنفِقُونَ ٩٢\nوهم سبعة نفر سموا بالبكائين... أتوا رسول الله -صلى الله عليه وسلم-، فقالوا: يا رسول الله، إن الله قد ندبنا إلى الخروج معك؛ فاحملنا... فأجابهم النبي -صلى الله عليه وسلم- كما أخبر الله عنه في قوله تعالى: ﴿قُلۡتَ لَآ أَجِدُ مَآ أَحۡمِلُكُمۡ عَلَيۡهِ﴾ تولوا وهم يبكون. البغوي:٢/٣١٥.\nرأينا في زماننا من يبكي لخسارة فريق رياضي أو شهوة نفسية أو منفعة دنيوية، ما الذي أبكى الصحابة -رضي الله عنهم-؟\nإِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ وَهُمۡ أَغۡنِيَآءُۚ رَضُواْ بِأَن يَكُونُواْ مَعَ ٱلۡخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَعۡلَمُونَ ٩٣\n﴿فَهُمۡ لَا يَعۡلَمُونَ﴾ أي: لا علم لهم؛ فلذلك جهلوا ما في الجهاد من منافع الدارَين لهم، فلذلك رضوا بما لا يرضى به عاقل، وهو أبلغ مِن نفي الفقه في الأولى. البقاعي:٣/٣٧٥.\nما الحكمة في ختم الآية بوصف المتخلفين عن الجهاد بعدم العلم، ووصفهم قبل ذلك بعدم الفقه؟"],[202,"§التوبة\nwords\nلَن نُؤمِنَ لَكُملَن نُصَدِّقَكُم.\nوَأَجدَرُأَحَقُّ، وَأَحرَى.\nمَغرَمًاغَرَامَةً، وَخَسَارَةً.\nوَيَتَرَبَّصُيَنتَظِرُ.\nالدَّوَائِرَالحَوَادِثَ وَالآفَاتِ.\nعَلَيهِم دَائِرَةُ السَّوءِدُعَاءٌ بِالشَّرِّ وَالعَذَابِ يَدُورُ عَلَيهِم.\ndeeds\nاعمل اليوم حسنة بالسر، لا يطلع عليها أحد إلا الله تعالى.\nأكثر في صلاتك اليوم من قول: \"ربِّ زدني علمًا\".\nتصدَّق اليوم وأنت مستشعر أن الصدقة تقربك من الله تعالى.\nguid\nاستشعار المراقبة سبب لإصلاح العمل.\nرضا الله تعالى مقدم على رضا الناس، ومن رضي الله عنه أرضى عنه الصالحين من خلقه.\nالقرب من العلماء والدعاة سببٌ للبعد عن الجهل.\nrefl\nوَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ\nلأن العمل ميزان الصدق من الكذب، وأمَّا مجرد الأقوال فلا دلالة فيها على شيء من ذلك. السعدي:٣٤٨.\nما الميزان الذي تختبر فيه صدقك من كذبك تجاه الدين؟\nيَحۡلِفُونَ لَكُمۡ لِتَرۡضَوۡاْ عَنۡهُمۡۖ فَإِن تَرۡضَوۡاْ عَنۡهُمۡ فَإِنَّ ٱللَّهَ لَا يَرۡضَىٰ عَنِ ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ ٩٦\nفرضانا عن القوم الفاسقين ليس مما يحبه الله ويرضاه؛ وهو لا يرضى عنهم. ابن تيمية:٣/٤٣٨.\nهل الرضى عن فسق القوم الفاسقين جائز؟ وهل ينفعهم ذلك شيئًا؟\nٱلۡأَعۡرَابُ أَشَدُّ كُفۡرٗا وَنِفَاقٗا وَأَجۡدَرُ أَلَّا يَعۡلَمُواْ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦۗ\nوذلك لبعدهم عن سماع القرآن، ومعرفة السنن. البغوي:٢/٣١٧.\nما الأثر الذي يحدث لمن ابتعد عن مواطن العلم والعلماء؟\nٱلۡأَعۡرَابُ أَشَدُّ كُفۡرٗا وَنِفَاقٗا وَأَجۡدَرُ أَلَّا يَعۡلَمُواْ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦۗ\nوفي هذه الآية دليل على... فضيلة العلم، وأن فاقده أقرب إلى الشر ممن يعرفه؛ لأن الله ذم الأعراب، وأخبر أنهم أشد كفرًا ونفاقًا، وذكر السبب الموجب لذلك، وأنهم أجدر أن لا يعلموا حدود ما أنزل الله على رسوله. السعدي:٣٤٩.\nكيف تدل هذه الآية على فضيلة العلم والعلماء؟\nوَمِنَ ٱلۡأَعۡرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغۡرَمٗا وَيَتَرَبَّصُ بِكُمُ الدَّوآئٍر عَلَيِهم دائِرة السَّوءِ واللَّهُ سَمِيعٌ عَلِيمٌ\n﴿وَمِنَ ٱلۡأَعۡرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغۡرَمًا﴾ أي: تثقل عليهم الزكاة والنفقة في سبيل الله ثقل المغرم الذي ليس بحق عليه. ﴿وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَۚ﴾ أي: ينتظر بكم مصائب الدنيا. ﴿عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۗ﴾: خبر، أو دعاء. ابن جزي:١/٣٦٨.\nما رأيك في من يدّعي الإسلام، ويفرح بما يصيب المسلمين من أذى؟\nوَمِنَ ٱلۡأَعۡرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغۡرَمٗا\nفي الآية دليل على... أنه ينبغي للمؤمن أن يؤدي ما عليه من الحقوق منشرح الصدر، مطمئن النفس، ويحرص أن تكون مغنمًا، ولا تكون مغرمًا. السعدي:٣٤٩.\nما الحال التي يجب أن يكون عليها المسلم حال تأديته الواجبات التي عليه؟\nوَمِنَ ٱلۡأَعۡرَابِ مَن يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِۚ\n﴿وَصَلَوَٰتِ ٱلرَّسُولِۚ﴾ أي: وسببًا لدعائه -عليه الصلاة والسلام-؛ فإنه -صلى الله عليه وسلم- كان يدعو للمتصدقين بالخير والبركة، ويستغفر لهم؛ ولذلك يُسَنُّ للمتصدَّق عليه أن يدعوَ للمتصدِّق عند أخذ صدقته. الألوسي:١١/١١.\nماذا يستحب للمتصدَّق عليه عند أخذ الصدقة؟"],[203,"§التوبة\nwords\nمَرَدُوالَجُّوا فِيهِ، وَاستَمَرُّوا عَلَيهِ، وَدَرَبُوا.\nوَتُزَكِّيهِم بِهَاتُرَفِّعُهُم بِهَا عَن مَنَازِلِ المُنَافِقِينَ.\nوَصَلِّ عَلَيهِمادعُ لَهُم بِالمَغفِرَةِ.\nسَكَنٌ لَهُمرَحمَةٌ، وَطُمَأنِينَةٌ لَهُم.\nمُرجَونَمُؤَخَّرُونَ.\ndeeds\nاسبق اليوم إلى عمل خير وبر وطاعة، أو مشروع دعوي وخيري؛ لعلك تكتب عند الله تعالى من السابقين.\nأرسل رسالة تترضى فيها عن أصحاب رسول الله -صلى الله عليه وسلم- وتنشر مآثرهم، وترد على من آذاهم وتَعرَّض لهم.\nتصدق بصدقة ترجو بها طهارة قلبك وتزكيته؛ لعل الله يحقق رجاءك بها.\nguid\nمن منهج أهل السنة والجماعة اتباع الصحابة والتابعين، وجعلهم قدوةً؛ وهو سببٌ لنيل رضوان الله -عز وجل-.\nرضي الله عن الصحابة؛ فمن رضي عنهم فهو القريب من الله، ومن سخط عليهم فهو البعيد من الله سبحانه.\nما يخفيه الإنسان هو الباعث له على أعماله الظاهرة.\nrefl\nوَٱلسَّٰبِقُونَ ٱلۡأَوَّلُونَ مِنَ ٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحۡسَٰنٖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُ وَأَعَدَّ لَهُمۡ جَنَّٰتٖ تَجۡرِي تَحۡتَهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ١٠٠\nالسبق إلى الهجرة طاعة عظيمة، من حيث إن الهجرة فعل شاق على النفس، ومخالف للطبع؛ فمن أقدم عليه أولًا صار قدوة لغيره في هذه الطاعة. القاسمي:٤/١٩١.\nلمَ علّق الله -تعالى- الفضل والأجر الكبير لمن سبق للهجرة والنصرة؟\nوَٱلسَّٰبِقُونَ ٱلۡأَوَّلُونَ مِنَ ٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحۡسَٰنٖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُ\nفرضي عن السابقين من غير اشتراط إحسان، ولم يرض عن التابعين إلا أن يتبعوهم بإحسان... والرضى من الله صفة قديمة؛ فلا يرضى إلا عن عبد علم أنه يوافقه على موجبات الرضى، ومن رضي الله عنه لم يسخط عليه أبدًا. ابن تيمية:٣/٤٤٠.\nبيّن فضل الصحابة من خلال الآية الكريمة.\nوَمِمَّنۡ حَوۡلَكُم مِّنَ ٱلۡأَعۡرَابِ مُنَٰفِقُونَۖ وَمِنۡ أَهۡلِ ٱلۡمَدِينَةِ مَرَدُواْ عَلَى ٱلنِّفَاقِ لَا تَعۡلَمُهُمۡۖ نَحۡنُ نَعۡلَمُهُمۡۚ سَنُعَذِّبُهُم مَّرَّتَيۡنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٖ ١٠١\nولعل تكرير عذابهم لما فيهم من الكفر المشفوع بالنفاق. القاسمي:٤/١٩٣.\nما وجه تكرار العذاب في قوله: ﴿سَنُعَذِّبُهُم مَّرَّتَيۡنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍ﴾؟\nوَءَاخَرُونَ ٱعۡتَرَفُواْ بِذُنُوبِهِمۡ خَلَطُواْ عَمَلٗا صَٰلِحٗا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ١٠٢\nفهذه الآية دلت على أن المخلط المعترف النادم، الذي لم يتب توبة نصوحًا؛ أنه تحت الخوف والرجاء، وهو إلى السلامة أقرب. وأمَّا المخلط الذي لم يعترف ويندم على ما مضى منه، بل لا يزال مصرًا على الذنوب؛ فإنه يُخاف عليه أشد الخوف. السعدي:٣٥٠.\nالذين خلطوا بين عمل صالح وآخر سيئ هم على قسمين، ما هما؟\nخُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ\n﴿خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةً تُطَهِّرُهُمۡ﴾ بها من ذنوبهم، ﴿وَتُزَكِّيهِم بِهَا﴾ أي: ترفعهم من منازل المنافقين إلى منازل المخلصين. البغوي:٢/٣٢٢.\nاذكر شيئًا من بركات الصدقة على المؤمن.\nخُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ\nاستحباب الدعاء من الإمام أو نائبه لمن أدى زكاته بالبركة، وأن ذلك ينبغي أن يكون جهرًا؛ بحيث يسمعه المتصدق فيسكن له. ويؤخذ من المعنى: أنه ينبغي إدخال السرور على المؤمن بالكلام اللين، والدعاء له، ونحو ذلك مما يكون فيه طمأنينة وسكون لقلبه. وأنه ينبغي تنشيط من أنفق نفقة وعمل عملًا صالحًا بالدعاء له والثناء، ونحو ذلك. السعدي:٣٥١.\nما فائدة دعاء من يقبض الصدقة لأخيه المتصدق؟\nوَقُلِ ٱعۡمَلُواْ فَسَيَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ وَٱلۡمُؤۡمِنُونَۖ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ١٠٥\nأُمروا بالعمل عقب الإعلام بقبول توبتهم؛ لأنهم لمَّا قُبلت توبتهم كان حقًا عليهم أن يدلوا على صدق توبتهم، وفرط رغبتهم في الارتقاء إلى مراتب الكمال؛ حتى يَلحقوا بالذين سبقوهم، فهذا هو المقصود. ابن عاشور:١١/٢٥.\nلماذا أمر المؤمنون بالعمل عقب الإخبار عن قبول توبتهم؟"],[204,"§التوبة\nwords\nضِرَارًامُضَارَّةً لِلمُؤمِنِينَ.\nوَإِرصَادًاانتِظَارًا.\nشَفَاطَرَفِ.\nجُرُفٍ هَارٍ حُفرَةٍ مُتَدَاعِيَةٍ لِلسُّقُوطِ.\ndeeds\nاكتب رسالة موثقة تفضح فيها أحد مشاريع أهل النفاق.\nساعد اليوم إحدى المؤسسات المعروف أصحابها بالخير والصلاح.\nحاول أن تكون على طهارة طوال اليوم إن استطعت ذلك بلا مشقة.\nguid\nالشعارات البراقة للمنافقين والتظاهر بعمل الخير لا تخدع من يتدبر القرآن الكريم.\nلا تكن عونًا لمن يريد تمزيق شمل الأمة، أو إفساد جيلها، أو تغريب نسائها، وتذكر قول الله تعالى لنبيه.\nادع الله تعالى أن تكون أعمالك مبنية على تقوى الله تعالى، وطلب رضوانه، والإخلاص له.\nrefl\nوَٱلَّذِينَ ٱتَّخَذُواْ مَسۡجِدٗا ضِرَارٗا وَكُفۡرٗا وَتَفۡرِيقَۢا بَيۡنَ ٱلۡمُؤۡمِنِينَ وَإِرۡصَادٗا لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبۡلُۚ وَلَيَحۡلِفُنَّ إِنۡ أَرَدۡنَآ إِلَّا ٱلۡحُسۡنَىٰۖ وَٱللَّهُ يَشۡهَدُ إِنَّهُمۡ لَكَٰذِبُونَ ١٠٧\nفدخل في معنى ذلك من بنى أبنية يضاهي بها مساجد المسلمين لغير العبادات المشروعة من المشاهد وغيرها؛ لا سيما إذا كان فيها من الضرار والكفر والتفريق بين المؤمنين والإرصاد لأهل النفاق والبدع المحادّين لله ورسوله ما يقوى بها شَبَهُها بمسجد الضرار. ابن تيمية:٣/٤٤٧.\nهل تدخل المباني التي تنشر باطل أهل البدع في معنى مسجد الضرار؟ ولماذا؟\nوَٱلَّذِينَ ٱتَّخَذُواْ مَسۡجِدٗا ضِرَارٗا وَكُفۡرٗا وَتَفۡرِيقَۢا بَيۡنَ ٱلۡمُؤۡمِنِينَ\nأي: يفرقون به جماعتهم ليتخلف أقوام عن النبي -صلى الله عليه وسلم-، وهذا يدلك على أن المقصد الأكبر والغرض الأظهر من وضع الجماعة: تأليف القلوب والكلمة على الطاعة. البغوي ٢/٣٦٦.\nما المقصود من تشريع الصلاة في الجماعة؟ وكيف راعى الشرع هذا المقصد؟\nلَا تَقُمۡ فِيهِ أَبَدٗاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ\nالمعصية تؤثر في البقاع؛ كما أثرت معصية المنافقين في مسجد الضرار، ونُهي عن القيام فيه، وكذلك الطاعة تؤثر في الأماكن؛ كما أثرت في مسجد قباء، حتى قال الله فيه: ﴿لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِ﴾؛ ولهذا كان لمسجد قباء من الفضل ما ليس لغيره، حتى كان النبي -صلى الله عليه وسلم- يزور قباء كل سبت يصلي فيه، وحث على الصلاة فيه. السعدي:٣٥٢.\nبركة الطاعة تتعداها إلى مكان فعلها، وشؤم المعصية يتعداها إلى مكان فعلها، وضِّح ذلك من خلال هذه الآية.\nلَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَن تَقُومَ فِيهِۚ\nيستفاد من الآية صحة ما اتفق عليه الصحابة -رضي الله تعالى عنهم أجمعين- مع عمر -رضي الله تعالى عنه- حين شاورهم في التاريخ فاتفق رأيهم على أن يكون من عام الهجرة؛ لأنه الوقت الذي أعزَّ اللهُ فيه الإسلام... فوافق رأيهم هذا ظاهر التنزيل، وفهمنا الآن بنقلهم أن قوله تعالى: ﴿مِنۡ أَوَّلِ يَوۡمٍ﴾ أن ذلك اليوم هو أول أيام التاريخ الذي نؤرخ به الآن. الألوسي:١١/٣١.\nاذكر مثالًا يبين دقة فهم الصحابة -رضي الله عنهم- للقرآن، وعملهم به.\nفِيهِ رِجَالٞ يُحِبُّونَ أَن يَتَطَهَّرُواْۚ وَٱللَّهُ يُحِبُّ ٱلۡمُطَّهِّرِينَ ١٠٨\nأثنى الله -سبحانه وتعالى- في هذه الآية على من أحب الطهارة وآثر النظافة؛ وهي مروءة آدمية، ووظيفة شرعية. القرطبي:١٠/٣٨١.\nما منزلة الطهارة والنظافة في ديننا الحنيف؟\nأَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ أَم مَّنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٖ فَٱنۡهَارَ بِهِۦ فِي نَارِ جَهَنَّمَۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٠٩\nوتأسيس البناء على التقوى والرضوان هو: بحسن النية فيه، وقصد وجه الله، وإظهار شرعه. والتأسيس على شفا جرف هار هو: بفساد النية، وقصد الرياء، والتفريق بين المؤمنين؛ فذلك على وجه الاستعارة والتشبيه البديع. ابن جزي: ٣٦٩.\nمتى يكون تأسيس البناء على التقوى؟ ومتى يكون تأسيسه على شفا جرف هار؟\nإِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ فَيَقۡتُلُونَ وَيُقۡتَلُونَۖ وَعۡدًا عَلَيۡهِ حَقّٗا فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ وَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُواْ بِبَيۡعِكُمُ ٱلَّذِي بَايَعۡتُم بِهِۦۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ١١١\nوإذا أردت أن تعرف مقدار الصفقة فانظر إلى: المشتري من هو؛ وهو الله -جل جلاله-. وإلى العِوَض؛ وهو أكبر الأعواض وأجلها: جنات النعيم. وإلى الثمن المبذول فيها؛ وهو النفس والمال الذي هو أحب الأشياء للإنسان. وإلى من جرى على يديه عقد هذا التبايع؛ وهو أشرف الرسل. وبأيِّ كتاب رُقِمَ؛ وهي كتب الله الكبار المنَزلة على أفضل الخلق. السعدي:٣٥٣.\nما مقدار عظمة هذه الصفقة والبيعة بين الله والمؤمنين؟"],[205,"§التوبة\nwords\nالسَّائِحُونَالصَّائِمُونَ.\nسَاعَةِ العُسرَةِوَقتِ الشِّدَّةِ، وَالمُرَادُ: غَزوَةُ تَبُوكٍ.\nيَزِيغُيَمِيلُ.\ndeeds\nبعد تأمل معنى الأعمال الواردة في الآية ومعرفتها، اعمل ما تستطيع منها.\nاجمع آيات الولاء والبراء، ثم اطلع على تفسيرها، وارجع لأهل العلم المعتبرين، وتفقه منهم في هذا الباب.\nادع الله تعالى أن يرزقك الحلم، وعود نفسك عليه؛ حتى تكون متصفًا به.\nguid\nعِظَم شعيرة الأمر بالمعروف والنهي عن المنكر، فهل أدركنا هذه الحقيقة؟\nحقيقة الإيمان تقتضي تقديم المؤمن ولو كان بعيد النسب، وتأخير الكافر ولو كان قريب النسب.\nطاعة الله تعالى في المكاره الشاقة على النفس من أسباب توبة الله تعالى على العبد.\nrefl\nٱلتَّٰٓئِبُونَ ٱلۡعَٰبِدُونَ ٱلۡحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلۡأٓمِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَٰفِظُونَ لِحُدُودِ ٱللَّهِۗ\n(العابدون) أي: المتصفون بالعبودية لله، والاستمرار على طاعته من أداء الواجبات والمستحبات في كل وقت؛ فبذلك يكون العبد من العابدين. السعدي:٣٥٣.\nمتى يُوصف الإنسان بأنه عابد؟\nوَبَشِّرِ ٱلۡمُؤۡمِنِينَ ١١٢\nلم يذكر ما يبشرهم به ليعم جميع ما رُتِّبَ على الإيمان من ثواب الدنيا والدين والآخرة؛ فالبشارة متناولة لكل مؤمن، وأمَّا مقدارها وصفتها فإنها بحسب حال المؤمنين وإيمانهم؛ قوةً وضعفًا، وعملًا بمقتضاه. السعدي:٣٥٣.\nلماذا لم يذكر الله -سبحانه وتعالى- المبشر به؟\nمَا كَانَ لِلنَّبِيِّ وَٱلَّذِينَ ءَامَنُوٓاْ أَن يَسۡتَغۡفِرُواْ لِلۡمُشۡرِكِينَ وَلَوۡ كَانُوٓاْ أُوْلِي قُرۡبَىٰ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَٰبُ ٱلۡجَحِيمِ ١١٣\nفإن النبي والذين آمنوا معه عليهم أن يوافقوا ربهم في رضاه وغضبه، ويوالوا من والاه الله، ويعادوا من عاداه الله. والاستغفار منهم لمن تبين أنه من أصحاب النار منافٍ لذلك، مناقض له. السعدي:٢٥٣.\nمن خلال الآية: بَيِّن شيئًا من عقيدة الولاء والبراء.\nوَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٖ ١١٦\nولما كان الإنسان قد ينصره غير قريبه؛ قال: ﴿وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ﴾ أي: فلا توالوا إلا مَن كان من حزبه وأهل حبه وقُربه. وفيه تهديد لمن أقدم على ما ينبغي أن يُتقى؛ لا سيما الملاينة لأعداء الله من المساترين والمصارحين؛ فإن غاية ذلك موالاتهم، وهي لا تغني من الله شيئًا. البقاعي:٣/٣٩٥.\nفي الآية إشارة إلى الولاء والبراء في الله تعالى وحده، بيِّن ذلك.\nلَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ\nوسماها ساعة تهوينًا لأوقات الكروب، وتشجيعًا على مواقعة المكاره؛ فإن أمدها يسير وأجرها عظيم. البقاعي:٣/٣٩٦.\nفي قوله: ﴿سَاعَةِ ٱلۡعُسۡرَةِ﴾ فائدة لطيفة، وضحها -وفقك الله لطاعته-.\nلَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٖ مِّنۡهُمۡ ثُمَّ تَابَ عَلَيۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفٞ رَّحِيمٞ ١١٧\nفإن قيل: كيف أعاد ذكر التوبة، وقد قال في أول الآية: ﴿لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ﴾؟ قيل: ذكر التوبة في أول الآية قبل ذكر الذنب، وهو محض الفضل من الله -عز وجل-، فلما ذكر الذنب أعاد ذكر التوبة، والمراد منه قبولها. البغوي:٢/٣٣٦.\nما الحكمة من إعادة ذكر التوبة في الآية؟\nلَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِيِّ وَٱلۡمُهَٰجِرِينَ وَٱلۡأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِي سَاعَةِ ٱلۡعُسۡرَةِ\nاجتمع عليهم عسرة الظهر، وعسرة الزاد، وعسرة الماء. القرطبي:١٠/٤٠٧.\nإلى أي حد بلغت العسرة بأصحاب النبي في غزوة تبوك؟"],[206,"§التوبة\nwords\nبِمَا رَحُبَتمَعَ رَحبِهَا وَسَعَتِهَا.\nمَخمَصَةٌمَجَاعَةٌ.\nنَيلًا قَتلًاأَو هَزِيمَةً، أو أذىً.\ndeeds\nاقرأ حديث كعب بن مالك -رضي الله عنه- في قصة تخلفه عن غزوة تبوك من أحد كتب السنة أو السيرة، ثم استخرج خمس فوائد منها.\nتقرب إلى الله بالتوبة من ذنب وقع منك.\nتذكر وأنت تسعى أو تشارك في عمل خير أن كل خطواتك محسوبة في ميزان حسناتك.\nguid\nالتائب الصادق قد يمتحن في صدق توبته وقوة ثباته.\nكل ميسر لما خلق له؛ فإن كنت من المؤهلين لطلب العلم فلا تشغلك الدنيا عنه.\nمن مهام طلبة العلم والعلماء إنذار قومهم وتحذيرهم.\nrefl\nوَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ\nتوبة الله على عبده بحسب ندمه وأسفه الشديد، وأن من لا يبالي بالذنب ولا يحرج إذا فعله فإن توبته مدخولة، وإن زعم أنها مقبولة. السعدي:٣٥٤.\nدلَّت الآية على ركن عظيم من أركان التوبة، فما هو؟\nوَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُواْ حَتَّىٰٓ إِذَا ضَاقَتۡ عَلَيۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَنفُسُهُمۡ وَظَنُّوٓاْ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيۡهِ ثُمَّ تَابَ عَلَيۡهِمۡ لِيَتُوبُوٓاْۚ\nعلامة الخير وزوال الشدة إذا تعلق القلب بالله تعالى تعلقًا تامًا وانقطع عن المخلوقين. السعدي:٣٥٤.\nمتى يحصل الفرج لصاحب الكرب؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَكُونُواْ مَعَ ٱلصَّٰدِقِينَ ١١٩\nيحتمل أن يريد صدق اللسان؛ إذ كانوا هؤلاء الثلاثة قد صدقوا ولم يعتذروا بالكذب، فنفعهم الله بذلك، ويحتمل أن يريد أعم من صدق اللسان؛ وهو الصدق في الأقوال، والأفعال، والمقاصد، والعزائم. ابن جزي:١/٣٧٢.\nالصدق صفة عظيمة لاشتمالها على أكثر من معنى، وضح ذلك.\nذَٰلِكَ بِأَنَّهُمۡ لَا يُصِيبُهُمۡ ظَمَأٞ وَلَا نَصَبٞ وَلَا مَخۡمَصَةٞ فِي سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوۡطِئٗا يَغِيظُ ٱلۡكُفَّارَ وَلَا يَنَالُونَ مِنۡ عَدُوّٖ نَّيۡلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٞ صَٰلِحٌۚ\nوالله سبحانه يأجر العبد على الأعمال المأمور بها مع المشقة؛ كما قال تعالى: ﴿ذَٰلِكَ بِأَنَّهُمۡ لَا يُصِيبُهُمۡ ظَمَأٌ وَلَا نَصَبٌ﴾ الآية، وقال -صلى الله عليه وسلم- لعائشة: «أجرك على قدر نصبك». ابن تيمية:٣/٤٦١.\nسيلقى المسلم أجر عمله، وأجر المشقة فيه، بين ذلك من الآية الكريمة.\nلِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ ١٢٢\nثم بيّن غاية العلم؛ مشيرًا إلى أنَّ مَن جعل له غاية غيرها مِن ترفع أو افتخار فقد ضلَّ ضلالًا كبيرًا؛ فقال موجبًا لقبول خَبَر مَن بلغهم: (لعلهم) أي كلهم (يحذرون) أي: ليكون حالهم حال أهل الخوف من الله بما حصلوا من الفقه؛ لأنه أصل كل خير؛ به تنجلي القلوب فتُقبِل على الخير، وتُعرِض عن الشر... والمراد بالفقه هنا: حفظ الكتاب والسنة، وفهم معانيهما من: الأصول، والفروع، والآداب، والفضائل. البقاعي:٣/٤٠٣.\nما رأيك في العلم الذي لا يَتبعُه خوفٌ من الله تعالى؟\nوَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِيَنفِرُواْ كَآفَّةٗۚ فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ ١٢٢\nفي هذه الآية أيضًا دليل وإرشاد، وتنبيه لطيف لفائدة مهمة؛ وهي: أن المسلمين ينبغي لهم أن يعدوا لكل مصلحة من مصالحهم العامة من يقوم بها، ويوفر وقته عليها، ويجتهد فيها، ولا يلتفت إلى غيرها؛ لتقوم مصالحهم، وتتم منافعهم، ولتكون وجهة جميعهم، ونهاية ما يقصدون قصدًا واحدًا؛ وهو قيام مصلحة دينهم ودنياهم ولو تفرقت الطرق وتعددت المشارب؛ فالأعمال متباينة، والقصد واحد، وهذه من الحكمة العامة النافعة في جميع الأمور. السعدي:٣٥٥.\nهذه الآية أساسٌ في علم إدارة الأعمال، وضِّح ذلك.\nوَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِيَنفِرُواْ كَآفَّةٗۚ فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةٖ مِّنۡهُمۡ طَآئِفَةٞ لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ ١٢٢\nمن تعلم علمًا فعليه نشره وبثه في العباد، ونصيحتهم فيه؛ فإن انتشار العلم عن العالم من بركته وأجره الذي يُنَمَّى له، وأمَّا اقتصار العالم على نفسه، وعدم دعوته إلى سبيل الله بالحكمة والموعظة الحسنة، وترك تعليم الجهال ما لا يعلمون؛ فأي منفعة حصلت للمسلمين منه؟! وأي نتيجة نتجت من علمه؟! وغايته أن يموت فيموت علمه وثمرته، وهذا غاية الحرمان لمن آتاه الله علمًا ومنحه فهمًا. السعدي:٣٥٥.\nما الطريقة المثلى لإفادة طالب العلم من علمه الذي حصله؟"],[207,"§التوبة\nwords\nيَلُونَكُمالقَرِيبِينَ مِنكُم.\nمَرَضٌشَكٌّ، وَنِفَاقٌ.\nرِجسًانِفَاقًا وَشَكًّا.\nيُفتَنُونَيُبتَلَونَ بِالقَحطِ وَالشِّدَّةِ، وَإِظهَارِ مَا يُبطِنُونَهُ مِنَ النِّفَاقِ.\nعَزِيزٌصَعبٌ، وَشَاقٌّ عَلَيهِ.\nمَا عَنِتُّمعَنَتُكُم، وَمَشَقَّتُكُم.\ndeeds\nمتى ما أحسست اليوم بضعف في إيمانك فاقرأ آيات من القرآن الكريم بنية زيادة الإيمان.\nقل: \"اللهم يا مصرف القلوب صرف قلبي على طاعتك ومحبتك\".\nقل: \"حسبي الله لا إله إلا هو عليه توكلتُ وهو رب العرش العظيم\".\nguid\nإذا أردت أن تنال معية الله تعالى فحقق التقوى؛ وذلك بتقديم أمر الله على هوى نفسك.\nإذا وجدت قلبك لا ينتفع بالقرآن فاعلم أن فيه مرضًا.\nذكرت الآية أربع صفات للنبي؛ حددها ثم حاول أن تتصف بها.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قَٰتِلُواْ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلۡكُفَّارِ وَلۡيَجِدُواْ فِيكُمۡ غِلۡظَةٗۚ\nفإن المؤمن الكامل هو الذي يكون رفيقًا لأخيه المؤمن، غليظًا على عدوه الكافر. ابن كثير:٢/٣٨٤.\nكيف تكون علاقة المؤمن بأخيه المؤمن، وعلاقته بالكافر المحارب؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قَٰتِلُواْ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلۡكُفَّارِ وَلۡيَجِدُواْ فِيكُمۡ غِلۡظَةٗۚ\nوالمقصد من ذلك: إلقاءُ الرعب في قلوب الأعداء؛ حتى يخشوا عاقبة التصدي لقتال المسلمين. ابن عاشور:١١/٦٣.\nما المقصد من أمر المجاهدين بالغلظة على المشركين؟\nوَإِذَا مَآ أُنزِلَتۡ سُورَةٞ فَمِنۡهُم مَّن يَقُولُ أَيُّكُمۡ زَادَتۡهُ هَٰذِهِۦٓ إِيمَٰنٗاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَزَادَتۡهُمۡ إِيمَٰنٗا وَهُمۡ يَسۡتَبۡشِرُونَ ١٢٤ وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ\nأي: من المنافقين من يقول بعضهم لبعض: أيكم زادته هذه إيمانًا -على وجه الاستخفاف بالقرآن- كأنهم يقولون: أي عجب في هذا؟! وأي دليل في هذا؟! ﴿فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَزَادَتۡهُمۡ إِيمَٰنًا﴾: وذلك لما يتجدد عندهم من البراهين والأدلة عند نزول كل سورة. ﴿وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ﴾:... والمعنى:... زادتهم كفرًا ونفاقًا إلى كفرهـم ونفاقهـم. ابـن جزي:١/٣٧٤.\nكيف كان في نزول الآية زيادة إيمان لبعض الناس، وزيادة نفاق لآخرين؟\nأَوَلَا يَرَوۡنَ أَنَّهُمۡ يُفۡتَنُونَ فِي كُلِّ عَامٖ مَّرَّةً أَوۡ مَرَّتَيۡنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمۡ يَذَّكَّرُونَ ١٢٦\nولا شك أن الفتنة - التي أشارت إليها الآية- كانت خاصة بأهل النفاق من أمراض تحل بهم، أو متالف تصيب أموالهم، أو جوائح تصيب ثمارهم، أو نقص من أنفسهم ومواليدهم؛ فإذا حصل شيئان من ذلك في السنة كانت الفتنة مرتين. ابن عاشور:١١/٦٧.\nما المراد بالفتنة في الآية الكريمة؟\nلَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡكُم بِٱلۡمُؤۡمِنِينَ رَءُوفٞ رَّحِيمٞ ١٢٨\n﴿حَرِيصٌ عَلَيۡكُم﴾ فيحب لكم الخير، ويسعى جهده في إيصاله إليكم، ويحرص على هدايتكم إلى الإيمان، ويكره لكم الشر، ويسعى جهده في تنفيركم عنه. (بالمؤمنين رؤوف رحيم) أي: شديد الرأفة والرحمة بهم؛ أرحم بهم من والديهم. السعدي:٣٥٧.\nما الصفات التي تجعل الداعية مقبولًا بين الناس؟\nلَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡكُم بِٱلۡمُؤۡمِنِينَ رَءُوفٞ رَّحِيمٞ ١٢٨\n﴿حَرِيصٌ عَلَيۡكُم﴾ أي: حريص على إيمانكم وسعادتكم. (بالمؤمنين رؤوف رحيم): سماه الله هنا باسمين من أسمائه. ابن جزي:١/٣٧٤.\nمحبة الله سبحانه تورث في العبد بعض الصفات، مثل لذلك من الآية.\nفَإِن تَوَلَّوۡاْ فَقُلۡ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ١٢٩\nوهذه الآية تفيد التنويه بهذه الكلمة المباركة؛ لأنه أمر بأن يقول هذه الكلمة بعينِها، ولم يؤمَر بمجرد التوكل. ابن عاشور:١١/٧٤.\nلم كان في الآية تنويه بفضل لفظ الدعاء الوارد فيها؟"],[208,"§يونس\nwords\nقَدَمَ صِدقٍأَجرًا حَسَنًا بِمَا قَدَّمُوا مِن صَالِحِ الأَعمَالِ.\nاستَوَى عَلَى العَرشِعَلاَ عَلَى العَرشِ عُلُوًّا يَلِيقُ بِجَلاَلِهِ وَعَظَمَتِهِ.\nبِالقِسطِبِالعَدلِ.\nحَمِيمٍمَاءٍ بَالِغٍ غَايَةَ الحَرَارَةِ.\nوَقَدَّرَهُ مَنَازِلَصَيَّرَ القَمَرَ ذَا مَنَازِلَ يَسِيرُ فِيهَا.\nاختِلاَفِتَعَاقُبِ.\ndeeds\nأرسل رسالة إلى أحد الدعاة تبشره أن ثباته على الدعوة علامة على صدقه.\nقل: \"اللهم إني أسالك شفاعة نبيك محمد -صلى الله عليه وسلم-\".\nتعرف على بعض علوم الفلك؛ ففيها زيادة إيمان.\nguid\nبشرى أهل الإيمان والعمل الصالح بما أعد لهم عند ربهم.\nعدم تورع أهل الكفر عن الكذب والتضليل.\nلا تطلب الشفاعة الأخروية من حي أو ميت، بل اطلبها ممن لا يشفع أحد إلا بإذنه.\nrefl\nالٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ ١\nووجه مناسبتها لسورة براءة: أن الأولى خُتِمت بذكر الرسول، وهذه ابتدأت به. وأيضًا أنَّ في الأولى بيانًا لما يقوله المنافقون عند نزول سورة من القرآن، وفي هذه بيان لمَا يقوله الكفار في القرآن. الألوسي:١١/٧٩.\nما وجه الارتباط بين آخر سورة التوبة وأول سورة يونس؟\nإِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ\nمع أنه قادر على خلقها في لحظة واحدة؛ ولكن لمَا له في ذلك من الحكمة الإلهية، ولأنه رفيق في أفعاله. السعدي:٣٥٧.\nلماذا لم يخلق الله السماوات والأرض دفعة واحدة؟\nمَا مِن شَفِيعٍ إِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ فَٱعۡبُدُوهُۚ أَفَلَا تَذَكَّرُونَ ٣\nفلا يقدم أحد منهم على الشفاعة -ولو كان أفضل الخلق- حتى يأذن الله، ولا يأذن إلا لمن ارتضى، ولا يرتضي إلا أهل الإخلاص والتوحيد له. السعدي: ٣٥٧.\nيشترط للشفاعة شرطان، ما هما؟\nإِنَّهُۥ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ بِٱلۡقِسۡطِۚ\n(بالقسط): أي: بالعدل؛ بيان لعلة الحياة بعد الموت؛ إذ هذه الدار دار عمل، والآخرة دار جزاء على هذا العمل؛ فلذا كان البعث واجبًا حتمًا لا بد منه. الجزائري:٢/٤٤٨.\nما الحكمة من بعث الناس بعد الموت؟\nوَٱلَّذِينَ كَفَرُواْ لَهُمۡ شَرَابٞ مِّنۡ حَمِيمٖ وَعَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡفُرُونَ ٤\nوخص الشراب من الحميم بالذكر من بين أنواع العذاب الأليم؛ لأنه أكره أنواع العذاب في مألوف النفوس. ابن عاشور:١١/٩٣.\nلم خص الشراب من الحميم بالذكر؟\nهُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ يُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ٥ إِنَّ فِي ٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَّقُونَ ٦\nفي هذه الآيات الحث والترغيب على التفكر في مخلوقات الله، والنظر فيها بعين الاعتبار؛ فإن بذلك تنفتح البصيرة، ويزداد الإيمان والعقل، وتقوى القريحة، وفي إهمال ذلك تهاون بما أمر الله به، وإغلاق لزيادة الإيمان، وجمود للذهن والقريحة. السعدي:٣٥٨.\nما أهمية التفكر والتدبر في مخلوقات الله الكونية؟\nإِنَّ فِي ٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَّقُونَ ٦\n﴿لَأٓيَٰتٍ لِّقَوۡمٍ يَتَّقُونَ﴾. وخصصهم سبحانه بالذكر؛ لأن التقوى هي الداعية للنظر والتدبر. الألوسي:١١/٩٧.\nما الصفة التي تدعو صاحبها إلى النظر والتدبر؟"],[209,"§يونس\nwords\nدَعوَاهُمدُعَاؤُهُم.\nيَعمَهُونَيَتَرَدَّدُونَ حَائِرِينَ.\nلِجَنبِهِمُضطَجِعًا.\nمَرَّ استَمَرَّعَلَى كُفرِهِ.\nالقُرُونَالأُمَمَ المُكَذِّبَةَ.\nخَلاَئِفَاستَخلَفنَاكُم مِن بَعدِ إِهلاَكِهِم.\ndeeds\nاستمع إلى موعظة تذكرك بالآخرة.\nاحمد الله رب العالمين بعد انتهائك اليوم من كل عمل صالح.\nتذكر اليوم ضرًّا أو مرضًا كشفه الله عنك، ثم اجتهد في حمده وشكره.\nguid\nنسيان الآخرة بداية الغفلة.\nما يقدره الله حولك من أحداث وأخبار ونوازل إنَّما هو تذكير لك؛ فاحذر أن تكون عنها غافلًا.\nالإيمان سبب من أسباب الهداية الربانية؛ فاحرص على زيادة إيمانك ليزيدك الله هداية.\nrefl\nإِنَّ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا وَرَضُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَٱطۡمَأَنُّواْ بِهَا وَٱلَّذِينَ هُمۡ عَنۡ ءَايَٰتِنَا غَٰفِلُونَ ٧ أُوْلَٰٓئِكَ مَأۡوَىٰهُمُ ٱلنَّارُ بِمَا كَانُواْ يَكۡسِبُونَ ٨\nقال الحسن: \"والله ما زينوها ولا رفعوها حتى رضوا بها\"، وهم غافلون عن آيات الله الكونية فلا يتفكرون فيها، والشرعية فلا يأتمرون بها، بأن (مأواهم) يوم معادهم (النار)، (جزاء على ما كانوا يكسبون) في دنياهم من الآثام والخطايا والإجرام. ابن كثير:٢/٣٨٩.\nاذكر علامة من علامات الرضا بالحياة الدنيا؟\nإِنَّ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا وَرَضُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَٱطۡمَأَنُّواْ بِهَا وَٱلَّذِينَ هُمۡ عَنۡ ءَايَٰتِنَا غَٰفِلُونَ\n﴿وَٱطۡمَأَنُّواْ بِهَا﴾ أي: ركنوا إليها، وجعلوها غاية مرامهم، ونهاية قصدهم؛ فسعوا لها، وأكبوا على لذاتها وشهواتها؛ بأي طريق حصلت حصلوها، ومن أي وجه لاحت ابتدروها، قد صرفوا إرادتهم ونياتهم وأفكارهم وأعمالهم إليها. ﴿وَٱلَّذِينَ هُمۡ عَنۡ ءَايَٰتِنَا غَٰفِلُونَ﴾: فلا ينتفعون بالآيات القرآنية، ولا بالآيات الأفقية والنفسية، والإعراض عن الدليل مستلزم للإعراض والغفلة عن المدلول المقصود. السعدي:٣٥٨.\nذكرت الآية مانعًا يمنع من الانتفاع بالآيات القرآنية، فما هو؟\nإِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡۖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ فِي جَنَّٰتِ ٱلنَّعِيمِ ٩\n﴿يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡۖ﴾ أي: يسددهم بسبب إيمانهم إلى الاستقامة، أو يهديهم في الآخرة إلى طريق الجنة. ابن جزي:١/٣٧٦.\nبيّن ثمرة الإيمان الواردة في هذه الآية.\nفِي جَنَّٰتِ ٱلنَّعِيمِ ٩\nأضافها الله إلى النعيم لاشتمالها على النعيم التام؛ نعيم القلب بالفرح والسرور، والبهجة والحبور، ورؤية الرحمن، وسماع كلامه، والاغتباط برضاه وقربه، ولقاء الأحبة والإخوان، والتمتع بالاجتماع بهم، وسماع الأصوات المطربات، والنغمات المشجيات، والمناظر المفرحات، ونعيم البدن بأنواع المآكل والمشارب والمناكح، ونحو ذلك مما لا تعلمه النفوس، ولا خطر ببال أحد، أو قدر أن يصفه الواصفون. السعدي:٣٥٩.\nما الذي نفيده من إضافة الجنات إلى النعيم؟\nدَعۡوَىٰهُمۡ فِيهَا سُبۡحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمۡ فِيهَا سَلَٰمٞۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ١٠\nفالتكاليف سقطت عنهم في دار الجزاء، وإنَّما بقي لهم أكمل اللذات، الذي هو ألذ عليهم من المآكل اللذيذة؛ ألا وهو ذكر الله الذي تطمئن به القلوب، وتفرح به الأرواح، وهو لهم بمنزلة النَّفَس، من دون كلفة ومشقة. السعدي:٣٥٩.\nنحن نعلم أن التكاليف تسقط عن الناس يوم القيامة، فكيف تصدر منهم هذه العبادات؟\nوَإِذَا مَسَّ ٱلۡإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوۡ قَاعِدًا أَوۡ قَآئِمٗا فَلَمَّا كَشَفۡنَا عَنۡهُ ضُرَّهُۥ مَرَّ كَأَن لَّمۡ يَدۡعُنَآ إِلَىٰ ضُرّٖ مَّسَّهُۥۚ\nوفي الآية ذمّ لمن يترك الدعاء في الرخاء ويهرعُ إليه في الشدة، واللائق بحال الكامل: التضرع إلى مولاه في السراء والضراء؛ فإن ذلك أرجى للإجابة؛ ففي الحديث: «تعرَّف على الله في الرخاء يعرفك في الشدة». الألوسي:١١/١٠٨.\nاذكر شيئًا من آداب الدعاء مما أشارت إليه الآية الكريمة.\nكَذَٰلِكَ زُيِّنَ لِلۡمُسۡرِفِينَ مَا كَانُواْ يَعۡمَلُونَ ١٢\n﴿مَا كَانُواْ يَعۡمَلُونَ﴾ من: الإعراض عن الذِّكر والدعاء، والانهماك في الشهوات. والإسراف: مجاوزة الحد، وسمُّوا أولئك مسرفين؛ لأن الله تعالى إنَّما أعطاهم القوى والمشاعر ليصرفوها إلى مصارفها، ويستعملوها فيما خُلِقت له من العلوم والأعمال الصالحة، وهم قد صرفوها إلى ما لا ينبغي مع أنها رأس مالهم. الألوسي:١١/١٠٨.\nالإسراف يكون في إنفاق المال، ويكون في أعمّ من ذلك؛ بيِّن المعنى العام للإسراف."],[210,"§يونس\nwords\nتِلقَاءِ نَفسِيمِن قِبَلِ نَفسِي.\nأَدرَاكُمأَعلَمَكُم.\ndeeds\nتذكر ذنبًا كبيرًا فعلته، وأكثر من الاستغفار وعمل الصالحات؛ لعل الله يغفره لك.\nحذر من حولك من الشرك بالله، وبين لهم أن من الشرك دعاء غير الله أو الاستشفاع بالأموات.\nأرسل رسالة تبين فيها أهمية الاجتماع، ونبذ الفرقة والاختلاف.\nguid\nالجمع بين المعصية وقلة الخوف من الله من علامات مرض القلب.\nالاستمرار في تذكر الآخرة حماية للإنسان من الوقوع في المعاصي.\nلو لم ينزل علينا هذا القرآن لكنا من أجهل الناس؛ فلنقم بحق هذا الكتاب العظيم.\nrefl\nوَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَاتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا ٱئۡتِ بِقُرۡءَانٍ غَيۡرِ هَٰذَآ أَوۡ بَدِّلۡهُۚ قُلۡ مَا يَكُونُ لِيٓ أَنۡ أُبَدِّلَهُۥ مِن تِلۡقَآيِٕ نَفۡسِيٓۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّۖ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ عَظِيمٖ ١٥\nوالتبديل الذي سألوه فيما ذكر: أن يحوّل آية الوعيد آية وعد، وآية الوعد وعيدًا، والحرامَ حلالًا، والحلال حرامًا، فأمر الله نبيَّه -صلى الله عليه وسلم- أن يخبرهم أن ذلك ليس إليه، وأن ذلك إلى من لا يُرَدُّ حكمه، ولا يُتَعَقَّب قضاؤه؛ وإنَّما هو رسول مبلّغ ومأمور مُتّبع. الطبري: ١٥/٤٠.\nبيّن خطورة تغيير أحكام الشريعة حسب الأهواء والمصالح.\nقَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا ٱئۡتِ بِقُرۡءَانٍ غَيۡرِ هَٰذَآ أَوۡ بَدِّلۡهُۚ\nفإن زعموا أن قصدهم أن يتبين لهم الحق بالآيات التي طلبوا فهم كَذَبَةٌ في ذلك؛ فإن الله قد بيَّن من الآيات ما يؤمن على مثله البشر، وهو الذي يصرفها كيف يشاء، تابعًا لحكمته الربانية ورحمته بعباده. السعدي:٣٦٠.\nالحوار لا يفيد منه الإنسان إلا إذا لازمه الصدق، وضح ذلك من الآية.\nقَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا\nدل قوله: (قال الذين لا يرجون لقاءنا...) الآية، أن الذي حملهم على هذا التعنت الذي صدر منهم هو عدم إيمانهم بلقاء الله، وعدم رجائه، وأن من آمن بلقاء الله فلا بد أن ينقاد لهذا الكتاب ويؤمن به؛ لأنه حسن القصد. السعدي:٣٦٠.\nما سبب تعنت المنافقين والكفار ومواقفهم تجاه القضايا الإسلامية والشرعية؟\nفَقَدۡ لَبِثۡتُ فِيكُمۡ عُمُرٗا مِّن قَبۡلِهِۦٓۚ\n﴿فَقَدۡ لَبِثۡتُ فِيكُمۡ عُمُرًا﴾ طويلًا تعرفون حقيقة حالي بأني أمي؛ لا أقرأ، ولا أكتب، ولا أدرس، ولا أتعلم من أحد؛ فأتيتكم بكتاب عظيم أعجز الفصحاء، وأعيا العلماء، فهل يمكن مع هذا أن يكون من تلقاء نفسي، أم هذا دليل قاطع أنه تنزيل من حكيم حميد؟! فلو أعملتم أفكاركم وعقولكم، وتدبرتم حالي وحال هذا الكتاب لجزمتم جزمًا لا يقبل الريب بصدقه، وأنه الحق الذي ليس بعده إلا الضلال، ولكن إذ أبيتم إلا التكذيب والعناد؛ فأنتم لا شك أنكم ظالمون. السعدي:٣٦٠.\nما المراد من إخبار النبي -صلى الله عليه وسلم- قومه أنه قد لبث فيهم عمرًا قبل البعثة؟\nوَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِۚ\nوكانوا معترفين بأن آلهتهم لم تشارك الله في خلق السموات والأرض، ولا خلق شيء؛ بل كانوا يتخذونهم شفعاء ووسائط؛ كما قال تعالى: ﴿وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمۡ وَلَا يَنفَعُهُمۡ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِۚ﴾. ابن تيمية:٣/٤٧٣.\nكيف ترد من الآية على من يصرف العبادة للقبور، ويقول نقصد شفاعتهم فقط؟\nوَيَقُولُونَ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۖ فَقُلۡ إِنَّمَا ٱلۡغَيۡبُ لِلَّهِ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ ٢٠\nقل: إنَّما سألتموني الغيب، وإنَّما الغيب لله؛ لا يعلم أحد لِم لَم يفعل ذلك، ولا يعلمه إلا هو. البغوي:٢/٣٥٦.\nظهرت بعض القنوات التي يدعي أصحابها أنهم يعلمون المغيبات ويردون المفقودات، فما عقيدة المؤمن تجاه ذلك؟\nوَيَقُولُونَ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۖ فَقُلۡ إِنَّمَا ٱلۡغَيۡبُ لِلَّهِ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ ٢٠\nولو علم الله منهم أنهم سألوا لك استرشادًا وتثبتًا لأجابهم، ولكن علم أنهم إنَّما يسألون عنادًا وتعنتًا؛ فتركهم فيما رابهم. ابن كثير:٢/٣٩٤.\nلماذا لم يستجب الله تعالى لطلبات المشركين في حصول الآيات التي تدل على صدق محمد -صلى الله عليه وسلم-؟"],[211,"§يونس\nwords\nالفُلكِالسُّفُنِ.\nعَاصِفٌشَدِيدَةُ الهُبُوبِ.\nيَبغُونَيُفسِدُونَ.\nزُخرُفَهَابَهجَتَهَا وَنَضَارَتَهَا.\nحَصِيدًامَحصُودَةً، مَقطُوعَةً.\nلَم تَغنَ بِالأَمسِلَم تَكُن قَائِمَةً بِالأَمسِ.\nدَارِ السَّلاَمِالجَنَّةِ.\ndeeds\nتذكر شدةً أو كربةً مرت عليك، ثم اشكر الله تعالى على نعمته بتفريجها، ولا تكن من الغافلين.\nتذكر عهدًا عاهدت الله به، ثم خالفته، وعد إلى الوفاء به.\nسل الله تعالى أن يرزقك دار السلام.\nguid\nتحسن الأحوال بعد الكربة والضيق من مظان الغفلة والبعد عن الله تعالى، إلا من كان حذرًا.\nلا تنس أن كل شيء تقوله أو تعمله فإنه مكتوب عليك، وأنت مجازى به يوم القيامة.\nاعلم أن كل بغي تبغيه وكل ظلم تظلمه؛ فإنه عائد إليك، وراجع وباله عليك.\nrefl\nوَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ مِّنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُمۡ إِذَا لَهُم مَّكۡرٞ فِيٓ ءَايَاتِنَاۚ\nوإسناد المساس إلى الضراء بعد إسناد الإذاقة إلى ضمير الجلالة من الآداب القرآنية؛ كما في قوله تعالى: ﴿وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ﴾ [الشعراء: ٨٠] ونظائره، وينبغي التأدب في ذلك؛ ففي الخبر: «اللهم إن الخير بيديك والشر ليس إليك». الألوسي:١١/١٢٤.\nترشدنا الآية القرآنية والحديث النبوي إلى أدب التحدث عن الله -عز وجل-؛ بيِّن ذلك، وفقك الله لكل خير.\nهُوَ ٱلَّذِي يُسَيِّرُكُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ وَجَرَيۡنَ بِهِم بِرِيحٖ طَيِّبَةٖ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفٞ وَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانٖ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ ٢٢\nفالآية دالة على أن المشركين لا يدعون غيره تعالى في تلك الحال، وأنت خبير بأن الناس اليوم إذا اعتراهم أمر خطير، وخطب جسيم في بر أو بحر؛ دعوا من لا يضر ولا ينفع، ولا يرى ولا يسمع؛ فمنهم من يدعو الخضر وإلياس... ومنهم من يستغيث بأحد الأئمة... ولا ترى فيهم أحدًا يخص مولاه بتضرعه ودعاه، ولا يكاد يمر له ببال أنه لو دعا الله تعالى وحده؛ ينجو من هاتيك الأهوال. الألوسي:١١/١٣٠.\nالمشركون المتأخرون أشد ممن نزلت فيهم الآية، بين ذلك من خلال الوقفة.\nهُوَ ٱلَّذِي يُسَيِّرُكُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰٓ إِذَا كُنتُمۡ فِي ٱلۡفُلۡكِ وَجَرَيۡنَ بِهِم بِرِيحٖ طَيِّبَةٖ وَفَرِحُواْ بِهَا جَآءَتۡهَا رِيحٌ عَاصِفٞ وَجَآءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانٖ وَظَنُّوٓاْ أَنَّهُمۡ أُحِيطَ بِهِمۡ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ لَئِنۡ أَنجَيۡتَنَا مِنۡ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ ٢٢\nالمضطر يجاب دعاؤه، وإن كان كافرًا؛ لانقطاع الأسباب، ورجوعه إلى الواحد رب الأرباب. القرطبي:١٠/٤٧٥.\nهل يجيب الله تعالى دعاء المضطر الكافر؟ ولماذا؟\nإِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ مِمَّا يَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا وَٱزَّيَّنَتۡ وَظَنَّ أَهۡلُهَآ أَنَّهُمۡ قَٰدِرُونَ عَلَيۡهَآ أَتَىٰهَآ أَمۡرُنَا لَيۡلًا أَوۡ نَهَارٗا فَجَعَلۡنَٰهَا حَصِيدٗا كَأَن لَّمۡ تَغۡنَ بِٱلۡأَمۡسِۚ\nفكان حال الدنيا في سرعة انقضائها، وانقراض نعيمها بعد عظيم إقباله؛ كحال نبات الأرض في جفافه وذهابه حطامًا بعدما التفَّ وزيَّن الأرض بخضرته وألوانه وبهجته. البقاعي:٣/٤٣٣.\nما وجه الشبه بين مراحل زينة الحياة الدنيا ومراحل زينة نبات الأرض؟\nأَتَىٰهَآ أَمۡرُنَا لَيۡلًا أَوۡ نَهَارٗا فَجَعَلۡنَٰهَا حَصِيدٗا كَأَن لَّمۡ تَغۡنَ بِٱلۡأَمۡسِۚ\nقال قتادة: ﴿كَأَن لَّمۡ تَغۡنَ﴾: \"كأن لم تنعم\"، وهكذا الأمور بعد زوالها: كأنها لم تكن؛ ولهذا جاء في الحديث: «يؤتى بأنعم أهل الدنيا، فيغمس في النار غمسة، ثم يقال له: هل رأيت خيرًا قط؟ [هل مر بك نعيم قط؟] فيقول: لا، ويؤتى بأشد الناس عذابًا في الدنيا، فيغمس في النعيم غمسة، ثم يقال له: هل رأيت بؤسًا قط؟ فيقول: لا». ابن كثير:٢/٣٩٥.\nفي هذه الآية تزهيد في جميع المعاصي ومتع الحياة الدنيا، وضِّح ذلك.\nكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَتَفَكَّرُونَ ٢٤\nوأما الغافل المعرض؛ فهذا لا تنفعه الآيات، ولا يزيل عنه الشك البيان. السعدي:٣٦٢.\nمتى يستفيد الإنسان من ضرب الأمثلة القرآنية؟\nوَٱللَّهُ يَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ\nلما ذكر تعالى الدنيا وسرعة زوالها، رغب في الجنة ودعا إليها، وسماها دار السلام؛ أي: من الآفات والنقائص والنكبات. ابن كثير:٢/٣٩٥.\nلماذا سُمِّيت الجنة بدار السلام؟"],[212,"§يونس\nwords\nيَرهَقُيَغشَى.\nقَتَرٌغُبَارٌ.\nعَاصِمٍمَانِعٍ يَمنَعُ عَذَابَ اللهِ.\nفَزَيَّلنَافَرَّقنَا.\nتَبلُوتُعَايِنُ، وَتَتَفَقَّدُ.\ndeeds\nاحرص اليوم أكثر أن لا تنظر إلى حرام، وأكثر من السجود رجاء أن ترى الله تعالى يوم القيامة.\nأحسن اليوم إلى مسلم إحسانًا يمنعه من أن يذل نفسه للمخلوقين؛ لعل الله يجازيك بالإحسان وزيادة يوم القيامة.\nتذكر الصعوبة والمشقة في تدبير أمور بيتكم، ثم تأمل كيف يدبر الله سبحانه أمور الكون كله ولا يشغله شأن عن شأن سبحانه.\nguid\nاحذر الفسق؛ فإنه دركات، وأسفلها مسببٌ للموت على الكفر -والعياذ بالله-.\nآثار المعصية على صاحبها كثيرة.\nفي الدنيا قد تتخلص من موقف بالكذب، لكن في الآخرة لن تستطيع ذلك.\nrefl\nلِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ وَلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَرٞ وَلَا ذِلَّةٌۚ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ ٢٦\nولما دعا إلى دار السلام، كأن النفوس تشوقت إلى الأعمال الموجبة لها الموصلة إليها؛ فأخبر عنها بقوله: ﴿۞لِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٌۖ﴾. السعدي:٣٦٢.\nما العلاقة بين هذه الآية والتي قبلها؟\nلِّلَّذِينَ أَحۡسَنُواْ ٱلۡحُسۡنَىٰ وَزِيَادَةٞۖ\nأي: للذين أحسنوا في عبادة الخالق؛ بأن عبدوه على وجه المراقبة والنصيحة في عبوديته، وقاموا بما قدروا عليه منها، وأحسنوا إلى عباد الله بما يقدرون عليه من الإحسان القولي والفعلي... فهؤلاء الذين أحسنوا لهم (الحسنى)؛ وهي الجنة الكاملة في حسنها، و(زيادة)؛ وهي النظر إلى وجه الله الكريم، وسماع كلامه، والفوز برضاه، والبهجة بقربه؛ فبهذا حصل لهم أعلى ما يتمناه المتمنون، ويسأله السائلون. السعدي:٣٦٢.\nكيف يكون المسلم من الذين أحسنوا؟\nوَلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَرٞ وَلَا ذِلَّةٌۚ\nأي: لا ينالهم مكروه بوجه من الوجوه؛ لأن المكروه إذا وقع بالإنسان تبين ذلك في وجهه، وتغير وتكدَّر. السعدي:٣٦٢.\nلماذا خَصَّ الله الوجه بأنه لا يناله شيء من المكدرات في الجنة؟\nوَقَالَ شُرَكَآؤُهُم مَّا كُنتُمۡ إِيَّانَا تَعۡبُدُونَ ٢٨\nوفي هذا تبكيتٌ عظيمٌ للمشركين الذين عبدوا مع الله غيره ممن لا يسمع ولا يبصر، ولا يغني عنهم شيئًا، ولم يأمرهم بذلك، ولا رضي به ولا أراده، بل تبرأ منهم وقت أحوج ما يكونون إليه. ابن كثير:٢/٣٩٧.\nصِفِ الصدمة العظيمة التي تصيب عباد الأصنام والأضرحة والقبور يوم القيامة حينما يقضى بينهم وبين ما يعبدون؟\nفَكَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنَنَا وَبَيۡنَكُمۡ إِن كُنَّا عَنۡ عِبَادَتِكُمۡ لَغَٰفِلِينَ ٢٩\n(كفى بالله شهيدًا بيننا وبينكم): في ذلك؛ يشهد أنكم لم تخصوا أحدًا منه ومنّا بعبادة، بل كنتم مذبذبين. وهذا كله إشارة إلى أن العبادة المشوبة لا اعتداد بها، ولا يرضاها جماد لو نطق، وأن من استحق العبادة استحق الإخلاص فيها، وأن لا يشرك به أحد، وأنه لا يستحق ذلك إلاّ القادر على كشف الكرب. البقاعي:٣/٤٣٧.\nمن المستحق لأن تصرف له العبادة؟ ولماذا؟\nإِن كُنَّا عَنۡ عِبَادَتِكُمۡ لَغَٰفِلِينَ ٢٩\n(لغافلين): لأنه لا أرواح فينا؛ فلم نكن بحيث نأمر بالعبادة ولا نرضاها؛ فاللوم عليكم دوننا. البقاعي:٣/٤٣٧.\nلماذا لا يرد المعبودون من دون الله على عابديهم في الدنيا؟\nفَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلۡحَقُّۖ فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَٰلُۖ فَأَنَّىٰ تُصۡرَفُونَ ٣٢\nتدل الآية على أنه ليس بين الحق والباطل منزلة في علم الاعتقادات؛ إذ الحق فيها في طرف واحد، بخلاف مسائل الفروع. ابن جزي:١/٣٨٠.\nكيف ترد بهذه الآية على من يُمَيِّع مسائل الاعتقاد، ويرى أن كل طائفة عندها نوع من الحق؟"],[213,"§يونس\nwords\nفَأَنَّى تُؤفَكُونَفَكَيفَ تُصرَفُونَ؟!\nلاَ يَهِدِّيلاَ يَهتَدِي.\nيَأتِهِم تَأوِيلُهُوَلَم يَأتِهِم بَعدُ حَقِيقَةُ مَا وُعِدُوا بِهِ فِي الكِتَابِ.\ndeeds\nحدد خبرًا سمعته أو قرأته اليوم، ثم اعرضه على قاعدة التثبت والتحقق لتعرف الصواب، وليكن ذلك منهجك.\nحدد أمرًا في العقيدة تجهله، واسأل عنه؛ فإنه لا يقبل الظن في أصل العقيدة، بل لا بد من العلم اليقيني فيها.\nحدد شخصًا أو مجموعة يذكرونك بالمعصية، واحتسب الأجر في ترك صحبتهم.\nguid\nعلى الإنسان أن يتثبت في الأمور، ولا يبادر بقبول شيء أو رده قبل أن يحيط به علمًا.\nالهدى جاء في القرآن مفصلًا، وأكملت بيانه السنة النبوية؛ فلا مرجع للهداية غير القرآن والسنة.\nاقرأ آيات التحدي، وتفكر في عجز المشركين.\nrefl\nوَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـًٔاۚ\n﴿وَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ﴾: يريد الرؤساء منهم؛ أي: ما يتبعون إلا حدسًا وتخريصًا في أنها آلهة، وأنها تشفع، ولا حجة معهم، وأمَّا أتباعهم فيتبعونهم تقليدًا. القرطبي:١٠/٥٠٢.\nما سبب ضلالة رؤساء البدعة، وما سبب ضلالة أتباعهم؟\nوَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَفۡعَلُونَ ٣٦\n﴿وَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ﴾ أي: غير تحقيق؛ لأنه لا يستند إلى برهان. (إن الظن لا يغني من الحق شيئًا): ذلك في الاعتقادات؛ إذ المطلوب فيها اليقين، بخلاف الفروع. ابن جزي:١/٣٨١.\nهل ينفع الظن والتقليد في مسائل الاعتقاد؟ وما الواجب في هذه المسائل؟\nوَتَفۡصِيلَ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ ٣٧\nالذي ربَّى جميع الخلق بنعمه، ومن أعظم أنواع تربيته: أن أنزل عليهم هذا الكتاب؛ الذي فيه مصالحهم الدينية والدنيوية، المشتمل على مكارم الأخلاق ومحاسن الأعمال. السعدي:٣٦٤.\nما العلاقة بين الكلام عن تفصيل الكتاب وختم الآية بصفة الربوبية؟\nبَلۡ كَذَّبُواْ بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ وَلَمَّا يَأۡتِهِمۡ تَأۡوِيلُهُۥۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ ٣٩\nومما يقصد من هذا التشبيه أمور؛ أحدها: أن هذه عادة المعاندين الكافرين؛ ليعلم المشركون أنهم مماثلون للأمم التي كذبت الرسل فيعتبروا بذلك. الثاني: التعريض بالنذارة لهم بحلول العذاب بهم كما حل بأولئك الأمم التي عرف السامعون مصيرها وشاهدوا ديارها. الثالث: تسلية النبي -صلى الله عليه وسلم- بأنه ما لقي من قومه إلا مثل ما لقي الرسل السابقون من أقوامهم. ابن عاشور:١١/١٧٣.\nمواقف المعاندين للدين عبر التاريخ متشابهة، بين ذلك من الآية.\nبَلۡ كَذَّبُواْ بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ وَلَمَّا يَأۡتِهِمۡ تَأۡوِيلُهُۥۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ ٣٩\nوفي هذا دليل على التثبت في الأمور، وأنه لا ينبغي للإنسان أن يبادر بقبول شيء أو رده قبل أن يحيط به علمًا. السعدي:٣٦٥.\nكيف يتعامل الإنسان مع الأخبار تصديقًا وتكذيبًا؟\nوَمِنۡهُم مَّن يَسۡتَمِعُونَ إِلَيۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُواْ لَا يَعۡقِلُونَ ٤٢\nمنهم من يستمعون إلى النبي وقت قراءته للوحي، لا على وجه الاسترشاد، بل على وجه التفرج والتكذيب وتطلب العثرات؛ وهذا استماع غير نافع ولا مُجدٍ على أهله خيرًا. السعدي:٣٦٥.\nلماذا لم يفد المشركون من سماعهم للقرآن؟\nوَمِنۡهُم مَّن يَسۡتَمِعُونَ إِلَيۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُواْ لَا يَعۡقِلُونَ ٤٢\nوجعلهم كالصم للختم على قلوبهم، والطبع عليها، أي: لا تقدر على هداية من أصمه الله عن سماع الهدى. القرطبي:١٠/٥٠٧.\nلماذا جعلهم الله تعالى كالصم مع كونهم لهم آذان وأسماع؟"],[214,"§يونس\nwords\nيَنظُرُ إِلَيكَيُبصِرُكَ، وَيُعَايِنُ أَدِلَّةَ نُبُوَّتِكَ الصَّادِقَةِ.\nأَرَأَيتُمأَخبِرُونِي.\nبَيَاتًالَيلًا.\nأَثُمَّأَبَعدَمَا\nوَيَستَنبِئُونَكَيَستَخبِرُونَكَ.\ndeeds\nأرسل رسالة، أو ألق كلمة تذكر فيها إخوانك بقصر المكوث في الدنيا.\nاقرأ كتابًا علميًّا موثقًا بالأدلة الصحيحة في صفات النبي -صلى الله عليه وسلم-، وما يقدر عليه وما لا يقدر.\nقل: \"اللهم إني أعوذ برضاك من سخطك، وبمعافاتك من عقوبتك\".\nguid\nالدنيا ساعة؛ فاعمرها بالطاعة.\nإذا ظُلِمت أو اعتدي على حقك فتذكر أن الله يقضي بالقسط يوم القيامة؛ فكن مطمئنًا.\nإذا كان الرسول لا يملك لنفسه نفعًا ولا ضرًا وهو أشرف الخلق، فكيف بمن هو دونه؟!\nrefl\nوَمِنۡهُم مَّن يَسۡتَمِعُونَ إِلَيۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُواْ لَا يَعۡقِلُونَ ٤٢ وَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ أَفَأَنتَ تَهۡدِي ٱلۡعُمۡيَ وَلَوۡ كَانُواْ لَا يُبۡصِرُونَ ٤٣\nفإذا فسدت عقولهم وأسماعهم وأبصارهم -التي هي الطرق الموصلة إلى العلم لمعرفة الحقائق- فأين الطريق الموصل إلى الحق؟! السعدي:٣٦٥.\nما طرق العلم؟ وكيف يفيد الإنسان منها إفادةً تامةً في معرفة شرع الله؟\nوَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ\nودل قوله: ﴿وَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ﴾ الآية، أن النظر إلى حالة النبي -صلى الله عليه وسلم- وهديه وأخلاقه وأعماله وما يدعو إليه من أعظم الأدلة على صدقه وصحة ما جاء به، وأنه يكفي البصير عن غيره من الأدلة. السعدي:٣٦٥.\nما أهمية دراسة السيرة النبوية وتدريسها؟\nوَمِنۡهُم مَّن يَنظُرُ إِلَيۡكَۚ أَفَأَنتَ تَهۡدِي ٱلۡعُمۡيَ وَلَوۡ كَانُواْ لَا يُبۡصِرُونَ ٤٣\nومنهم من ينظر إليك وإلى ما أعطاك الله من التؤدة والسمت والحسن والخلق العظيم والدلالة الظاهرة على نبوتك لأولي البصائر والنهى، وهؤلاء ينظرون كما ينظر غيرهم، ولا يحصل لهم من الهداية شيء كما يحصل لغيرهم؛ بل المؤمنون ينظرون إليك بعين الوقار، وهؤلاء الكفار ينظرون إليك بعين الاحتقار. ابن كثير:٢/٤٠٠.\nلم أفاد المسلمون من النظر في حال النبي -صلى الله عليه وسلم- وهديه ولم يفد منه المشركون؟\nإِنَّ ٱللَّهَ لَا يَظۡلِمُ ٱلنَّاسَ شَيۡـٔٗا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمۡ يَظۡلِمُونَ ٤٤\nبالكفر والمعصية، ومخالفة أمر خالقهم. القرطبي:١٠/٥٠٧.\nكيف يظلم الإنسان نفسه؟\nوَيَوۡمَ يَحۡشُرُهُمۡ كَأَن لَّمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيۡنَهُمۡۚ\nوهذا كله دليل على استقصار الحياة الدنيا في الدار الآخرة. ابن كثير: ٢/٤٠١.\nكيف تنظر إلى الحياة الدنيا في ضوء هذه الآية؟\nقُل لَّآ أَمۡلِكُ لِنَفۡسِي ضَرّٗا وَلَا نَفۡعًا إِلَّا مَا شَآءَ ٱللَّهُۗ\n﴿قُل لَّآ أَمۡلِكُ لِنَفۡسِي﴾: لا أقدر لها على شيء، ﴿ضَرًّا وَلَا نَفۡعًاۚ﴾ أي: دفع ضر، ولا جلب نفع، ﴿إِلَّا مَا شَآءَ ٱللَّهُۚ﴾ أن أملكه. البغوي:٢/٣٦٥\nإذا كان النبي -صلى الله عليه وسلم- لا يملك لنفسه ضرًّا ولا نفعًا، فهل يملكه لغيره؟\nقُلۡ أَرَءَيۡتُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُهُۥ بَيَٰتًا أَوۡ نَهَارٗا مَّاذَا يَسۡتَعۡجِلُ مِنۡهُ ٱلۡمُجۡرِمُونَ ٥٠\nسر إِيثار (بياتًا) على \"ليلًا\" مع ظهور التقابل فيه: الإشعار بالنوم والغفلة، وكونه الوقت الذي يبيت فيه العدو، ويتوقع فيه، ويغتنم فرصة غفلته؛ وليس في مفهوم الليل هذا المعنى. القاسمي:٤/٢٥٦.\nما وجه التعبير بـ (بياتًا) دون \"ليلًا\" في هذه الآية؟"],[215,"§يونس\nwords\nبِالقِسطِبِالعَدلِ.\nتَفتَرُونَتَكذِبُونَ.\nشَأنٍأَمرٍ مِن أُمُورِكَ.\nتُفِيضُونَتَشرَعُونَ فِيهِ، وَتَعمَلُونَهُ.\nيَعزُبُيَغِيبُ.\ndeeds\nافتد نفسك اليوم من عذاب الله تعالى؛ ولو بقليل مال، أو يسير طعام أو شراب، أو ركعة، أو سجدة؛ قبل أن تتمنى أن تفتدي بالدنيا وما فيها.\nاقرأ كتاب كشف الشبهات؛ حيث أجاب عن الشبهات بآيات القرآن الكريم.\nاقرأ القرآن راجيًا شفاء صدرك من الحزن والضيق، وإزالة الشبه والشكوك التي تعتري القلوب.\nguid\nمن لم يتحسر اليوم على ذنوبه وتقصيره ستعظم حسرته يوم القيامة.\nلتتعرف على مقدار حبك لله: راجع نفسك؛ هل فرحتك بمتاع الدنيا أكثر؟ أم فرحتك بفعل الطاعات أكثر؟\nإياك والقول على الله تعالى بلا علم؛ فإنه طريق الخسار.\nrefl\nأَلَآ إِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ أَلَآ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٥٥\nوتقييد نفي العلم بالأكثر إشارة إلى أن منهم من يعلم ذلك ولكنه يجحده مكابرةً. ابن عاشور:١١/٢٠٠.\nلماذا نفي العلم عن أكثرهم، ولم ينف عن جميعهم؟\nيَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَتۡكُم مَّوۡعِظَةٞ مِّن رَّبِّكُمۡ وَشِفَآءٞ لِّمَا فِي ٱلصُّدُورِ وَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ ٥٧\n﴿وَشِفَآءٌ لِّمَا فِي ٱلصُّدُورِ﴾ أي: يشفي ما فيها من الجهل والشك. ابن جزي:١/٣٨٢.\nلم كان القرآن شفاء لمَا في الصدور؟\nيَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَتۡكُم مَّوۡعِظَةٞ مِّن رَّبِّكُمۡ وَشِفَآءٞ لِّمَا فِي ٱلصُّدُورِ وَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ ٥٧\nوقد عبر عنه بأربع صفات؛ هي أصول كماله وخصائصه، وهي: أنه موعظة، وأنه شفاء لما في الصدور، وأنه هدى، وأنه رحمةٌ للمؤمنين. ابن عاشور:١١/٢٠١.\nوصف القرآن الكريم بأربع صفات هي أصول كماله، فما هي؟\nيَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَتۡكُم مَّوۡعِظَةٞ مِّن رَّبِّكُمۡ وَشِفَآءٞ لِّمَا فِي ٱلصُّدُورِ وَهُدٗى وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ ٥٧\n﴿وَشِفَآءٌ لِّمَا فِي ٱلصُّدُورِ﴾ أي: من الشك والنفاق والخلاف والشقاق، (وهدىً) أي: [ورشدٌ] لمن اتبعه، (ورحمةٌ) أي: نعمة، (للمؤمنين): خصهم لأنهم المنتفعون بالإيمان. القرطبي:١١/١٠.\nهل كل أحد ينتفع بموعظة القرآن ودوائه؟\nقُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَٰلِكَ فَلۡيَفۡرَحُواْ\nوإنَّما أمر الله تعالى بالفرح بفضله ورحمته؛ لأن ذلك مما يوجب انبساط النفس ونشاطها، وشكرها لله تعالى، وقوتها، وشدة الرغبة في العلم والإيمان الداعي للازدياد منهما. السعدي:٣٦٧.\nلماذا أمر الله تعالى بالفرح بفضل الله ورحمته؟\nوَمَا ظَنُّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ يَوۡمَ ٱلۡقِيَٰمَةِۗ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ ٦٠\n﴿وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ﴾ إما أن لا يقوموا بشكرها، وإما أن يستعينوا بها على معاصيه، وإما أن يُحَرِّموا منها ويردوا ما مَنَّ الله به على عباده. السعدي:٣٦٧.\nما صور عدم شكر النعمة؟\nوَمَا تَكُونُ فِي شَأۡنٖ وَمَا تَتۡلُواْ مِنۡهُ مِن قُرۡءَانٖ وَلَا تَعۡمَلُونَ مِنۡ عَمَلٍ إِلَّا كُنَّا عَلَيۡكُمۡ شُهُودًا إِذۡ تُفِيضُونَ فِيهِۚ وَمَا يَعۡزُبُ عَن رَّبِّكَ مِن مِّثۡقَالِ ذَرَّةٖ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ وَلَآ أَصۡغَرَ مِن ذَٰلِكَ وَلَآ أَكۡبَرَ إِلَّا فِي كِتَٰبٖ مُّبِينٍ ٦١\nيخبر تعالى عن عموم مشاهدته واطلاعه على جميع أحوال العباد في حركاتهم وسكناتهم، وفي ضمن هذا الدعوة لمراقبته على الدوام... فراقبوا الله في أعمالكم، وأدوها على وجه النصيحة والاجتهاد فيها، وإياكم وما يكره الله تعالى؛ فإنه مطلع عليكم، عالم بظواهركم وبواطنكم. السعدي:٣٦٧-٣٦٨.\nما المقصود من إخبار الله -سبحانه وتعالى- عباده بعلمه بجميع الأشياء؟"],[216,"§يونس\nwords\nسُبحَانَهُتَنَزَّهَ، وَتَقَدَّسَ.\nسُلطَانٍحُجَّةٍ، وَدَلِيلٍ.\ndeeds\nقل: \"اللهم اهدني فيمن هديت، وتولني فيمن توليت\".\nحدد أمورًا تعارض فيها شرع الله مع هوى نفسك، ثم اتخذ قرارًا جازمًا بتقديم شرعه على هوى نفسك؛ لتنال ولاية الله تعالى.\nرتب حياتك هذا اليوم لتنام من أول الليل، وتبدأ عملك من أول النهار؛ لتوافق الفطرة التي ارتضاها الله لك.\nguid\nكلما عارض شرع الله هوى نفسك فبادر بتقديم شرع الله؛ فهذه هي التقوى، وهي وسيلتك لنيل ولاية الله تعالى.\nالأولياء هم أهل الإيمان والتقوى كما في الآية، وهذا يخرج أهل الشرك والبدعة والفسق.\nإذا سمعت الأذى والبغي وسيئ القول فلا تحزن ولا تهتم؛ فإن الله معز دينه وأهل طاعته.\nrefl\nأَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ٦٢\nوإن كانوا يحزنون لما يصيبهم من أمور في الدنيا؛ كقول النبي -صلى الله عليه وسلم-: «وإنا لفراقك يا إبراهيم لمحزونون»، فذلك حزن وجداني لا يستقر، بل يزول بالصبر، ولكنهم لا يلحقهم الحزن الدائم؛ وهو حزن المذلة، وغلبة العدو عليهم، وزوال دينهم وسلطانهم. ابن عاشور:١١/٢١٨.\nما الحزن المنفي عن المتقين؟ وهل ينافي ما يصيبهم في الدنيا من أحزان؟\nٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ ٦٣\nودل قوله: ﴿وَكَانُواْ يَتَّقُونَ﴾ على أن التقوى ملازمة لهم؛ أخذًا من صيغة (وكانوا)، وأنها متجددة منهم؛ أخذًا من صيغة المضارع في قوله: (يتقون). ابن عاشور:١١/٢١٨.\nكيف دلت الآية على أن من صفات أولياء الله تعالى أنهم ملازمون للتقوى؟\nلَهُمُ ٱلۡبُشۡرَىٰ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۚ\nأما البشارة في الدنيا فهي: الثناء الحسن، والمودة في قلوب المؤمنين، والرؤيا الصالحة، وما يراه العبد من لطف الله به، وتيسيره لأحسن الأعمال والأخلاق، وصرفه عنه مساوئ الأخلاق. وأمَّا في الآخرة: فأولها البشارة عند قبض أرواحهم... وفي القبر ما يُبشَّر به من رضا الله تعالى والنعيم المقيم، وفي الآخرة تمام البشرى بدخول جنات النعيم، والنجاة من العذاب الأليم. السعدي:٣٦٨.\nاذكر صورًا من بشارة المؤمن في الحياة الدنيا وفي الآخرة.\nلَا تَبۡدِيلَ لِكَلِمَٰتِ ٱللَّهِۚ\nلأنه الصادق في قيله، الذي لا يقدر أحد أن يخالفه فيما قدره وقضاه. السعدي:٣٦٨.\nما الذي يجعلك تطمئن أنه لا تبديل لكلمات الله؟\nوَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعًاۚ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ٦٥\nوجملة: ﴿إِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعًاۚ﴾ تعليل لدفع الحزن عنه؛ ولذلك فصلت عن جملة النهي، كأنَّ النبي يقول: كيف لا أحزن والمشركون يتطاولون علينا ويتوعدوننا، وهم أهل عزة ومنعَة؟! فأجيب بأن عزتهم كالعدم؛ لأنها محدودة وزائلة، والعزة الحق لله الذي أرسلك. ابن عاشور:١١/٢٢١.\nبيّن عظيم الفرق بين عزة الله تعالى وعزة المشركين.\nقَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗاۗ سُبۡحَٰنَهُۥۖ هُوَ ٱلۡغَنِيُّۖ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ إِنۡ عِندَكُم مِّن سُلۡطَٰنِۢ بِهَٰذَآۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ٦٨\nوفي الآية دليل على أنَّ كلَّ قولٍ لا دليل عليه فهو جهالة، وأن العقائد لا بد لها من قاطع، وأن التقليد بمعزل عن الاهتداء. الألوسي:١١/٢٠٧.\nما خطورة ترك الدليل الصحيح والعلم الشرعي؟\nقُلۡ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ ٦٩\nلا ينجون، وقيل: لا يبقون في الدنيا. البغوي ٢/٣٧١.\nما عقوبة من افترى الكذب والباطل على الله تعالى؟"],[217,"§يونس\nwords\nكَبُرَعَظُمَ.\nفَأَجمِعُوااعزِمُوا، وَأَعِدُّوا.\nغُمَّةًمُستَتِرًا.\nخَلاَئِفَيَخلُفُونَ المُكَذِّبِينَ فِي الأَرضِ.\nوَمَلَإيهِأَشرَافِ قَومِهِ.\nلِتَلفِتَنَالِتَصرِفَنَا.\ndeeds\nأخبر بعض زملائك أو قرابتك عن قصة نبي الله تعالى نوح بعد قراءتها من بعض الكتب؛ فإن الله تعالى يقول لنبيه: ﴿وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ نُوحٍ﴾.\nساعد أحد الدعاة، أو إحدى المؤسسات الخيرية محتسبًا الأجر من الله تعالى.\nاستعذ بالله من أن يطبع على قلبك؛ فإن العبد إذا طُبع على قلبه لم يحمل الخير -والعياذ بالله-.\nguid\nلا ينجي المؤمن من أذى الخلق إلا الله تعالى، فاستعذ به وحده.\nإياك أن ترد الحق؛ فإن رده قد يسبب الطبع على قلبك، فلا تجد سبيلًا للتوبة بعد ذلك.\nالاتهامات الكاذبة أسلوب من أساليب أهل الباطل والظلم والفساد، قديمًا وحديثًا.\nrefl\nثُمَّ لَا يَكُنۡ أَمۡرُكُمۡ عَلَيۡكُمۡ غُمَّةٗ ثُمَّ ٱقۡضُوٓاْ إِلَيَّ وَلَا تُنظِرُونِ ٧١\n﴿ثُمَّ ٱقۡضُوٓاْ إِلَيَّ﴾ أي: انفذوا فيما تريدون، ومعنى الآية: أن نوحًا -عليه السلام- قال لقومه: إن صَعُب عليكم دعائي لكم إلى الله فاصنعوا بي غاية ما تريدون، وإني لا أبالي بكم؛ لتوكلي على الله، وثقتي به سبحانه. ابن جزي:١/٣٨٥.\nالقوة في المواقف لا تأتي من فراغ، ولكنها تبنى على عمل من أعمال القلوب؛ فما هو؟\nفَإِن تَوَلَّيۡتُمۡ فَمَا سَأَلۡتُكُم مِّنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ\n﴿فَمَا سَأَلۡتُكُم﴾ على تبليغ الرسالة والدعوة ﴿مِّنۡ أَجۡرٍۖ﴾: جُعل وعوض، ﴿إِنۡ أَجۡرِيَ﴾: ما أجري وثوابي ﴿إِلَّا عَلَى ٱللَّهِۖ﴾. البغوي:٢/٣٧٢\nذكرت الآية علامة من علامات صدق الداعية تفرق فيها بين علماء السنة وعلماء البدعة؛ فما هي؟\nفَكَذَّبُوهُ فَنَجَّيۡنَٰهُ وَمَن مَّعَهُۥ فِي ٱلۡفُلۡكِ وَجَعَلۡنَٰهُمۡ خَلَٰٓئِفَ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بَِٔايَٰتِنَاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ ٧٣\nوتقدم ذكر إنجائه قبل ذكر الإغراق -الذي وقع الإنجاء منه- للإشارة إلى أن إنجاءه أهم عند الله تعالى من إغراق مكذبيه، ولتعجيل المسرة للمسلمين السامعين لهذه القصة. ابن عاشور:١١/٢٤٣.\nما فائدة تقديم ذكر إنجاء الله تعالى نوحًا -عليه السلام- على ذكر إغراق قومه؟\nثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِۦ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَمَا كَانُواْ لِيُؤۡمِنُواْ بِمَا كَذَّبُواْ بِهِۦ مِن قَبۡلُۚ كَذَٰلِكَ نَطۡبَعُ عَلَىٰ قُلُوبِ ٱلۡمُعۡتَدِينَ ٧٤\n﴿عَلَىٰ قُلُوبِ ٱلۡمُعۡتَدِينَ﴾ أي: المتجاوزين عن الحدود المعهودة في الكفر والعناد، ونمنعها لذلك عن قَبول الحق، وسلوك سبيل الرشاد. الألوسي:١١/٢١٦.\nما موانع الهداية والتوفيق للاستقامة كما بينت الآية الكريمة؟\nثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ بِـَٔايَٰتِنَا فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ ٧٥\nوكثيرًا ما يذكر الله تعالى قصة موسى -عليه السلام- مع فرعون في كتابه العزيز؛ لأنها من أعجب القصص؛ فإن فرعون حذر من موسى كل الحذر، فسخره القدر أن ربى هذا الذي يحذر منه على فراشه ومائدته بمنزلة الولد، ثم ترعرع وعقد الله له سببًا أخرجه من بين أظهرهم، ورزقه النبوة والرسالة والتكليم، وبعثه إليه ليدعوه إلى الله تعالى. ابن كثير:٢/٤٠٨.\nلماذا تتكرر كثيرًا قصة موسى -عليه السلام- مع فرعون في القرآن الكريم؟\nقَالُوٓاْ أَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلۡكِبۡرِيَآءُ فِي ٱلۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِنِينَ ٧٨\n﴿وَتَكُونَ لَكُمَا ٱلۡكِبۡرِيَآءُ﴾ أي: العظمة والملك والسلطان. القرطبي:١١/٢٨.\nاتهام الدعاة بأنهم يريدون من دعوتهم المناصب أسلوب قديم، وضح ذلك من الآية.\nقَالُوٓاْ أَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلۡكِبۡرِيَآءُ فِي ٱلۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِنِينَ ٧٨\nالحجج لا تُدفع إلا بالحجج والبراهين، وأمَّا من جاء بالحق فرُدَّ قوله بأمثال هذه الأمور؛ فإنها تدل على عجز مُورِدِها عن الإتيان بما يرُدُّ القول الذي جاء به خصمه؛ لأنه لو كان له حجة لأوردها، ولم يلجأ إلى قوله: قصدك كذا ومرادك كذا، سواء كان صادقًا في قوله وإخباره عن قصد خصمه أم كاذبًا. السعدي:٣٧١.\nفي الآية أسلوب من أساليب أهل الباطل في الحوار، وضحه."],[218,"§يونس\nwords\nوَيُحِقُّيُثبِتُ وَيُعلِي.\nتَبَوَّءَااتَّخِذَا.\nاطمِس عَلَى أَموَالِهِمأَتلِفهَا.\nوَاشدُد عَلَى قُلُوبِهِماختِم عَلَيهَا حَتَّى لاَ تُؤمِنَ.\ndeeds\nأرسل رسالة تحذر فيها من السحر وأهله.\nادع بهذا الدعاء على من اشتد في حربه على الإسلام والمسلمين.\nاقرأ هذه الآيات المباركات على نفسك، وعلى من به عين أو سحر؛ فإن لها تأثيرًا بإذن الله تعالى.\nguid\nالأعمال الفاسدة إلى زوال وإن قويت، والأعمال الصالحة باقية تمكث وتنفع صاحبها والناس.\nفئة الشباب أقبل للحق من غيرهم؛ فلا تهملهم في دعوتك مهما كثر الاستهتار والعبث عندهم.\nوجوب التوكل على الله تعالى لتحمل عبء الدعوة إلى الله تعالى والقيام بطاعته.\nrefl\nفَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ ٨٠\nوإنَّما أمرهم موسى بأن يبتدئوا بإلقاء سحرهم إظهارًا لقوة حجته؛ لأن شأن المبتدئ بالعمل المتباري فيه أن يكون أمكن في ذلك العمل من مباريه؛ ولاسيما الأعمال التي قوامها التمويه والترهيب، والتي يتطلَّب المستنصر فيها السبق إلى تأثر الحاضرين وإعجابهم. ابن عاشور:١/٢٥٤.\nلماذا أمر موسى -عليه السلام- السحرةَ بالابتداء بإلقاء سحرهم؟\nفَلَمَّآ أَلۡقَوۡاْ قَالَ مُوسَىٰ مَا جِئۡتُم بِهِ ٱلسِّحۡرُۖ إِنَّ ٱللَّهَ سَيُبۡطِلُهُۥٓ إِنَّ ٱللَّهَ لَا يُصۡلِحُ عَمَلَ ٱلۡمُفۡسِدِينَ ٨١\nوإنَّما كان السحرة مفسدين؛ لأن قصدهم تضليل عقول الناس، ليكونوا مسخرين لهم، ولا يعلموا أسباب الأشياء؛ فيبقوا آلة فيما تأمرهم السحرة، ولا يهتدوا إلى إصلاح أنفسهم سبيلًا. أما السحرة الذين خاطبهم موسى-عليه السلام- فإفسادهم أظهر؛ لأنهم يحاولون إبطال دعوة الحق، والدين القويم، وترويج الشرك والضلالات. ابن عاشور:١١/٢٥٧.\nالسحرة طبقات في إفسادهم، وضح ذلك.\nإِنَّ ٱللَّهَ لَا يُصۡلِحُ عَمَلَ ٱلۡمُفۡسِدِينَ ٨١\nوهكذا كل مفسد عمل عملًا واحتال كيدًا أو أتى بمكر؛ فإن عمله سيبطل ويضمحل، وإن حصل لعمله روجان في وقت ما فإن مآله الاضمحلال والمحق. وأمَّا المصلحون -الذين قصدهم بأعمالهم وجه الله تعالى، وهي أعمال ووسائل نافعة مأمور بها- فإن الله يصلح أعمالهم، ويرقيها، وينميها على الدوام. السعدي:٣٧١.\nما مآل الأعمال الفاسدة؟ وما مآل الأعمال الصالحة؟\nفَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٞ مِّن قَوۡمِهِۦ\nأي: شباب من بني إسرائيل... والحكمة -والله أعلم- بكونه ما آمن لموسى إلا ذرية من قومه: أن الذرية والشباب أقبل للحق، وأسرع له انقيادًا، بخلاف الشيوخ ونحوهم ممن تربى على الكفر؛ فإنهم -بسبب ما مكث في قلوبهم من العقائد الفاسدة- أبعد من الحق من غيرهم. السعدي:٣٧١.\nما السبب في كون أكثر من آمن مع موسى هم الشباب؟\nفَقَالُواْ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ ٨٥\nأي: لا تمكنهم من عذابنا، فيقولون: لو كان هؤلاء على الحق ما عذبناهم؛ فيفتنون بذلك. ابن جزي:١/٣٨٦.\nما مقصد موسى -عليه السلام- وقومه من هذا الدعاء؟\nفَقَالُواْ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ ٨٥ وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ٨٦\nتقديم التوكل على الدعاء، -وإن كان بيانًا لامتثال أمر موسى -عليه السلام- لهم، به تلويح بأن الداعي حقه أن يبني دعاءه على التوكل على الله تعالى؛ فإنه أرجى للإجابة، ولا يتوهمن أن التوكل منافٍ للدعاء؛ لأنه أحد الأسباب للمقصود. الألوسي:١١/٢٢٦.\nهل التوكل الصحيح يتعارض مع الدعاء؟\nفَلَا يُؤۡمِنُواْ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ ٨٨\nوهذه الدعوة كانت من موسى -عليه السلام- غضبًا لله ولدينه على فرعون وملئه الذين تبين له أنهم لا خير فيهم، ولا يجيء منهم شيء؛ كما دعا نوح -عليه السلام- فقال: ﴿وَقَال نُوحٞ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَٰفِرِينَ دَيَّارًا ٢٦ إِنَّكَ إِن تَذَرۡهُمۡ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِرٗا كَفَّارٗا ٢٧﴾ [نوح: ٢٦- ٢٧]. ابن كثير:٢/٤١١.\nما وجه دعاء موسى على فرعون وقومه؟"],[219,"§يونس\nwords\nفَاستَقِيمَافاثبُتَا عَلَى الدِّينِ، واستَمِرَّا علَى الدَّعوَةِ.\nوَلاَ تَتَّبِعَانِّلاَ تَسلُكَا.\nوَجَاوَزنَاقَطَعنَا.\nبَغيًا وَعَدوًاظُلمًا، وَعُدوَانًا.\nنُنَجِّيكَنُخرِجُكَ مِنَ البَحرِ، وَنَجعَلُكَ عَلَى مُرتَفِعٍ مِنَ الأَرضِ.\nبَوَّأنَاأَنزَلنَا.\nمُبَوَّأَ صِدقٍمَنزِلًا صَالِحًا بِالشَّامِ وَمِصرَ.\ndeeds\nألح على الله تعالى بالدعاء في أمر يهمك؛ محسنًا الظن به سبحانه.\nتذكر ذنبًا فعلته، ثم بادر بالتوبة قبل أن تصل إلى حالة لا تقبل فيها توبتك.\nاجمع اسئلة أشكلت عليك، ثم اتصل بأحد أهل العلم، واسأله عنها.\nguid\nقد تستجاب دعوتك بعد مدة.\nاحرص على التأمين حال سماعك الدعاء؛ فإن التأمين بمنزلة الدعاء.\nبادر بالتوبة؛ فقد يكون انتهاء وقتها مفاجئًا لك.\nrefl\nقَالَ قَدۡ أُجِيبَت دَّعۡوَتُكُمَا\nالخطاب لموسى وهارون؛ على أنه لم يذكر الدعاء إلا عن موسى وحده، لكن كان موسى يدعو وهارون يؤمن على دعائه. ابن جزي:١/٣٨٧.\nفي الآية دليل على أن الدعاء يستجاب من الداعي والمؤمِّن عليه، وضح ذلك.\nقَالَ قَدۡ أُجِيبَت دَّعۡوَتُكُمَا فَٱسۡتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعۡلَمُونَ ٨٩\nفرَّع على إجابة دعوتهما أمرهما بالاستقامة؛ فعُلم أن الاستقامة شكر على الكرامة؛ فإن إجابة الله دعوة عبده إحسان للعبد وإكرام، وتلك نعمة عظيمة تستحق الشكر عليها، وأعظم الشكر طاعة المنعم... والاستقامة حقيقتها: الاعتدال، وهي ضد الاعوجاج، وهي مستعملة كثيرًا في معنى ملازمة الحق والرشد. ابن عاشور:١١/٢٧٣\nما المقصود بالاستقامة؟ ولماذا أمر بها بعد الإخبار بإجابة دعوتهما؟\nحَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ ٩٠\nوالإيمان لا ينفع حينئذ، والتوبة مقبولة قبل رؤية البأس؛ وأمَّا بعدها وبعد المخالطة فلا تقبل. القرطبي:١١/٤٥.\nمتى ينتهي قبول الإيمان والتوبة؟\nحَتَّىٰٓ إِذَآ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِيٓ ءَامَنَتۡ بِهِۦ بَنُوٓاْ إِسۡرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِينَ ٩٠\nكما جرت عادة الله أن الكفار إذا وصلوا إلى هذه الحالة الاضطرارية أنه لا ينفعهم إيمانهم؛ لأن إيمانهم صار إيمانًا مشاهدًا كإيمان من ورد القيامة، والذي ينفع إنَّما هو الإيمان بالغيب. السعدي:٣٧٢.\nلماذا لم يقبل إيمان فرعون؟ وما الإيمان الذي يريده الله -سبحانه وتعالى-؟\nوَإِنَّ كَثِيرٗا مِّنَ ٱلنَّاسِ عَنۡ ءَايَٰتِنَا لَغَٰفِلُونَ ٩٢\nفلذلك تمر عليهم وتتكرر فلا ينتفعون بها؛ لعدم إقبالهم عليها. وأمَّا من له عقل وقلب حاضر؛ فإنه يرى من آيات الله ما هو أكبر دليل على صحة ما أخبرت به الرسل. السعدي:٣٧٣.\nما السبب الذي يجعل أكثر الناس لا ينتفعون بآيات الله، مع كثرة مرورها عليهم؟\nفَمَا ٱخۡتَلَفُواْ حَتَّىٰ جَآءَهُمُ ٱلۡعِلۡمُۚ\nوهذا هو الداء الذي يعرض لأهل الدين الصحيح؛ وهو أن الشيطان إذا أعجزوه أن يطيعوه في ترك الدين بالكلية، سعى في التحريش بينهم وإلقاء العداوة والبغضاء، فحصل من الاختلاف ما هو موجب ذلك، ثم حصل من تضليل بعضهم لبعض وعداوة بعضهم لبعض ما هو قرة عين اللَّعين. وإلا فإذا كان ربهم واحدًا، ورسولهم واحدًا، ودينهم واحدًا، ومصالحهم العامة متفقة؛ فلأي شيء يختلفون اختلافًا يفرق شملهم ويشتت أمرهم ويحل رابطتهم ونظامهم، فيفوت من مصالحهم الدينية والدنيوية ما يفوت، ويموت من دينهم بسبب ذلك ما يموت. السعدي:٣٧٣.\nما الداء الذي أصاب هذه الأمة وأضعفها مع وجود العلم الصحيح عندها؟\nفَإِن كُنتَ فِي شَكّٖ مِّمَّآ أَنزَلۡنَآ إِلَيۡكَ فَسۡـَٔلِ ٱلَّذِينَ يَقۡرَءُونَ ٱلۡكِتَٰبَ مِن قَبۡلِكَۚ\nوفي الآية تنبيه على أن من خالجته شبهة في الدِّين ينبغي له مراجعة مَن يزيلها من أهل العلم، بل المسارعة إلى ذلك حسبما تدل عليه الفاء الجزائية؛ بناءً على أنها تفيد التعقيب. الألوسي:١١/٢٥٢.\nما علاج الشبهات التي ترِد على النفس؟"],[220,"§يونس\nwords\nالرِّجسَالعَذَابَ.\nوَمَا تُغنِيلا تَنفَعُ.\nخَلَوامَضَوا.\nأَقِم وَجهَكَ لِلدِّينِأَقِم نَفسَكَ عَلَى الإِسلاَمِ مُستَقِيمًا عَلَيهِ.\nحَنِيفًامَائِلًا عَنِ الشِّركِ إِلَى التَّوحِيدِ.\ndeeds\nاجلس منفردًا، وتفكر في السماء أو في الجبال وما فيها من آيات وعبر.\nقل: \"اللهم إني أعوذ بك أن أشرك بك وأنا أعلم وأستغفرك لما لا أعلم\".\nاكتب هذه الآية، وأرسلها لمن يدعو غير الله.\nguid\nقبول التوبة قبل حصول العذاب ورؤية العلامات.\nتذكر أن الهداية والإيمان بيد الله تعالى، ولو شاء لجعل الناس كلهم مؤمنين.\nعند إهلاك الله للظلمة والمشركين فوعده تعالى ثابت لأوليائه بإنجائهم من الهلاك.\nrefl\nفَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ\nأي: لم يكن منهم أحد انتفع بإيمانه حين رأى العذاب... والحكمة في هذا ظاهرة؛ فإن الإيمان الاضطراري ليس بإيمان حقيقة، ولو صرف عنه العذاب والأمر الذي اضطره إلى الإيمان لرجع إلى الكفران. السعدي:٣٧٤.\nلماذا لا ينفع إيمان من أتاه العذاب؟\nفَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوۡمَ يُونُسَ لَمَّآ ءَامَنُواْ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ ٩٨\nولعل الحكمة في ذلك أن غيرهم من المهلكين لو ردوا لعادوا لما نهوا عنه، وأمَّا قوم يونس؛ فإن الله علم أن إيمانهم سيستمر، بل قد استمر فعلًا وثبتوا عليه. السعدي:٣٧٤.\nما الحكمة في تخصيص قوم يونس بأن نفعهم الإيمان بعد وقوع العذاب؟\nوَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ كُلُّهُمۡ جَمِيعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ ٩٩\nهذه تسلية للنبي؛ وذلك أنه كان حريصًا على أن يؤمن جميع الناس، فأخبره -جل ذكره- أنه لا يؤمن إلا من قد سبق له من الله السعادة، ولا يضل إلا من سبق له الشقاوة. البغوي ٢/٣٨١.\nإلى أي حد بلغت رحمة نبينا بأمته؟\nفَهَلۡ يَنتَظِرُونَ إِلَّا مِثۡلَ أَيَّامِ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِهِمۡۚ\nأي: فهل ينتظر هؤلاء الذين لا يؤمنون بآيات الله -بعد وضوحها- إلا ﴿مِثۡلَ أَيَّامِ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِهِمۡۚ﴾ أي: من الهلاك والعقاب؛ فإنهم صنعوا كصنيعهم، وسنة الله جارية في الأولين والآخرين. السعدي:٣٧٤.\nوضح في ضوء الآية سنة الله تعالى في الذين لا يؤمنون بآياته.\nثُمَّ نُنَجِّي رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ حَقًّا عَلَيۡنَا نُنجِ ٱلۡمُؤۡمِنِينَ ١٠٣\nفهو سبحانه أحقَّه على نفسه بحكم إحسانه وفضله ووعده، لا هم أحقوه عليه؛ كالحق الذي لإنسان على من له عنده يد. ابن تيمية: ٣/٥٠١.\nما معنى أن يكون هناك حق على الله تعالى؟\nثُمَّ نُنَجِّي رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ حَقًّا عَلَيۡنَا نُنجِ ٱلۡمُؤۡمِنِينَ ١٠٣\nمن سنتنا إذا أنزلنا بقوم عذابًا أخرجنا من بينهم الرسل والمؤمنين. القرطبي:١١/٥٨.\nهل يصيب عذاب الاستئصال من كان على إيمان وهدى؟\nوَلَا تَدۡعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَۖ فَإِن فَعَلۡتَ فَإِنَّكَ إِذٗا مِّنَ ٱلظَّٰلِمِينَ ١٠٦\nوالمقصود من هذا الفرض تنبيه الناس على فظاعة عظم هذا الفعل حتى لو فعله أشرف المخلوقين لكان من الظالمين. ابن عاشور:١١/٣٠٥.\nإذا كان النبي لا يمكن أن يدعو من دون الله أحدًا فما المقصود من مخاطبته بذلك؟"],[221,"§هود ، يونس\nwords\nفُصِّلَتبُيِّنَت بِالأَمرِ وَالنَّهيِ.\nتُوبُوا إِلَيهِارجِعُوا إِلَيهِ نَادِمِينَ.\nيَثنُونَ صُدُورَهُميُضمِرُونَ فِي صُدُورِهِمُ الكُفرَ.\nلِيَستَخفُوا مِنهُلِيَستَتِرُوا مِنَ اللهِ.\nيَستَغشُونَيَتَغَطَّونَ بِثِيَابِهِم.\ndeeds\nاستغفر الله تعالى، وتب إليه اليوم سبعين مرة.\nحدد أكبر أمنياتك أو احتياجاتك، وألح على الله بطلبها محسنًا الظن به سبحانه.\nاستعذ بالله من الحسد؛ فإن الله تعالى إذا كتب فضلًا لأحد من عباده فإنه لا راد لعطائه وكرمه.\nguid\nاصبر على طاعة الله وعن معاصيه؛ فإن المتبع للوحي يتعرض للشدائد، وخاصة في أزمنة الفتن.\nاعلم أن الله تعالى هو خير الحاكمين؛ الذي قضى بنصر عباده المؤمنين، ورفع ذكرهم، وكبت عدوهم.\nمظهر من مظاهر إعجاز القرآن؛ وهو أنه مؤلف من الحروف المقطعة، ولم تستطع العرب الإتيان بسورة مثله.\nrefl\nوَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يُرِدۡكَ بِخَيۡرٖ فَلَا رَآدَّ لِفَضۡلِهِۦۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦۚ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ١٠٧\nفإذا عرف العبد بالدليل القاطع أن الله هو المنفرد بالنعم، وكشف النقم، وإعطاء الحسنات، وكشف السيئات والكربات، وأن أحدًا من الخلق ليس بيده من هذا شيء إلا ما أجراه الله على يده؛ جزم بأن الله هو الحق، وأن ما يدعون من دونه هو الباطل. السعدي:٣٧٥.\nمن خلال الآية وضح كيف تنصح من يتعلق بالخلق وينسى الخالق.\nوَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ وَٱصۡبِرۡ حَتَّىٰ يَحۡكُمَ ٱللَّهُۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ ١٠٩\nقد قرن الصبر بالأعمال الصالحة عمومًا وخصوصًا؛ فقال تعالى: ﴿وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ وَٱصۡبِرۡ حَتَّىٰ يَحۡكُمَ ٱللَّهُۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ﴾. وفي اتباع ما أوحي إليه التقوى كلها؛ تصديقًا لخبر الله، وطاعة لأمره. ابن تيمية:٣/٥٠١.\nما الوسيلة الصادقة لتحقيق تقوى الله سبحانه؟\nالٓرۚ كِتَٰبٌ أُحۡكِمَتۡ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتۡ مِن لَّدُنۡ حَكِيمٍ خَبِيرٍ ١\nوأما سورة هود فإنما فيها ذكر الأمم، وما حل بهم من عاجل بأس الله تعالى؛ فأهل اليقين إذا تلوها تراءى على قلوبهم من ملكه وسلطانه ولحظاته البطش بأعدائه، فلو ماتوا من الفزع لحُقَّ لهم، ولكن الله -تبارك وتعالى اسمه- يلطف بهم في تلك الأحايين حتى يقرؤوا كلامه. القرطبي:١١/٦٤.\nما موضوع سورة هود، وما أثره على أهل الإيمان والصلاح إذا تلوها؟\nمِن لَّدُنۡ حَكِيمٍ خَبِيرٍ ١\nفإذا كان إحكامه وتفصيله من عند الله الحكيم الخبير؛ فلا تسأل بعد هذا عن عظمته، وجلاله، واشتماله على كمال الحكمة وسعة الرحمة. السعدي:٣٧٦.\nما الذي يُفاد من كون الكتاب أنزل من عند الحكيم الخبير؟\nوَأَنِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُمَتِّعۡكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَيُؤۡتِ كُلَّ ذِي فَضۡلٖ فَضۡلَهُۥۖ وَإِن تَوَلَّوۡاْ فَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ كَبِيرٍ ٣\nقال بعض الصلحاء: \"الاستغفار بلا إقلاع توبة الكذابين\". وقيل: إنَّما قدم ذكر الاستغفار لأن المغفرة هي الغرض المطلوب، والتوبة هي السبب إليها؛ فالمغفرة أول في المطلوب وآخر في السبب. ويحتمل أن يكون المعنى: استغفروه من الصغائر، وتوبوا إليه من الكبائر. القرطبي:١١/٦٧.\nلماذا قدم الاستغفار على التوبة في الآية؟\nوَأَنِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُمَتِّعۡكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٖ مُّسَمّٗى وَيُؤۡتِ كُلَّ ذِي فَضۡلٖ فَضۡلَهُۥۖ وَإِن تَوَلَّوۡاْ فَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ كَبِيرٍ ٣\nيعيشكم عيشًا حسنًا؛ في خفض ودَعَة، وأمن وسعة،... ويؤت كل ذي عمل صالح في الدنيا أجره، وثوابه في الآخرة. البغوي:٢/٣٨٥-٣٨٦\nما ثمرات الاستغفار؟\nأَلَآ إِنَّهُمۡ يَثۡنُونَ صُدُورَهُمۡ لِيَسۡتَخۡفُواْ مِنۡهُۚ أَلَا حِينَ يَسۡتَغۡشُونَ ثِيَابَهُمۡ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ٥\nقيل: كان الكفار إذا لقيهم رسول الله -صلى الله عليه وسلم- يردون إليه ظهورهم لئلَّا [يروه]؛ من شدة البغض والعداوة. ابن جزي:١/٣٩٠.\nما المقصود بثني الكفار لصدورهم؟ ولماذا يفعلون ذلك؟"],[222,"§هود\nwords\nمُستَقَرَّهَامَسكَنَهَا فِي الدُّنيَا، وَبَعدَ المَوتِ.\nوَمُستَودَعَهَاالمَوضِعَ الَّذِي تَمُوتُ فِيهِ.\nأُمَّةٍ مَعدُودَةٍأَجَلٍ مَعلُومٍ.\nمَا يَحبِسُهُمَا يَمنَعُهُ\nوَحَاقَأَحَاطَ بِهِم مِن كُلِّ جَانِبٍ.\ndeeds\nتأمل الحشرات الصغيرة، وكيف ضمن خالقها لها رزقها، ثم اعمل بأحد أسباب الرزق المباحة متوكلًا على الله سبحانه.\nتذكر نعمة أنعم الله بها عليك، ثم سلبك إياها، واشكره على تقديره أولًا وآخرًا.\nتأمل نفسك؛ فإن وجدت سبب ضيق صدرك هو فقدان زينة الدنيا فأكثر من الاستغفار.\nguid\nسعة علم الله تعالى وتكفله بأرزاق خلقه.\nلا تغتر بإمهال الله تعالى لأهل معصيته.\nقيمة العبد عند ربه بعمله الصالح لا بماله.\nrefl\nوَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلّٞ فِي كِتَٰبٖ مُّبِينٖ ٦\nوعدٌ وضمان صادق، فإن قيل: كيف قال: ﴿عَلَى ٱللَّهِ﴾ بلفظ الوجوب، وإنَّما هو تفضل؛ لأن الله لا يجب عليه شيء؟ فالجواب: أنه ذكره كذلك تأكيدًا في الضمان؛ لأنه لمَّا وعد به صار واقعًا لا محالة؛ لأنه لا يخلف الميعاد. ابن جزي:١/٣٩١.\nكيف أوجب الله تعالى على نفسه أمرًا هو في الأصل تفضّل منه -جل وعلا-؟\nلِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۗ\nولم يقل: \"أكثر عملًا\"، بل: ﴿أَحۡسَنُ عَمَلًاۗ﴾، ولا يكون العمل حسنًا حتى يكون خالصًا لله -عز وجل- على شريعة رسول الله -صلى الله عليه وسلم-؛ فمتى فقد العمل واحدًا من هذين الشرطين حبط وبطل. ابن كثير:٢/٤١٩.\nما الفرق بين \"أكثر عملًا\" و﴿أَحۡسَنُ عَمَلًاۗ﴾؟ ولماذا اختيرت الصيغة الثانية؟\nلِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۗ\nوالتقوى في العمل بشيئين؛ أحدهما: إخلاصه لله؛ وهو أن يريد به وجه الله لا يشرك بعبادة ربه أحدًا، والثاني: أن يكون مما أمره الله به وأحبه؛ فيكون موافقًا للشريعة لا من الدين الذي شرعه من لم يأذن الله له؛ وهذا كما قال الفضيل بن عياض في قوله: ﴿لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلًاۗ﴾، قال: \"أخلصه وأصوبه\". ابن تيمية:٣/٥٠٧.\nكيف يكون إحسان العمل؟\nوَلَئِنۡ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ ثُمَّ نَزَعۡنَٰهَا مِنۡهُ إِنَّهُۥ لَيَـُٔوسٞ كَفُورٞ ٩ وَلَئِنۡ أَذَقۡنَٰهُ نَعۡمَآءَ بَعۡدَ ضَرَّآءَ مَسَّتۡهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّيٓۚ إِنَّهُۥ لَفَرِحٞ فَخُورٌ ١٠\nوذلك أن الإنسان هو كما وصفه الله:... عند الضراء بعد السراء ييأس من زوالها في المستقبل، ويكفر بما أنعم الله به عليه قبلها، وعند النعماء بعد الضراء يأمن من عود الضراء في المستقبل، وينسى ما كان فيه بقوله: (ذهب السيئات عني إنه لفرح فخور). ابن تيمية:٣/٥٠٨.\nبيّن حال الإنسان عند الابتلاء بالسراء، وعند الابتلاء بالضراء.\nإِلَّا ٱلَّذِينَ صَبَرُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ أُوْلَٰٓئِكَ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ ١١\nومن معاني الصبر: انتظار الفرج؛ ولذلك أوثرَ هنا وصفُ: (صبروا) دون \"آمنوا\"؛ لأنّ المرادَ مقابلة حالهم بحال الكفّار في قوله: ﴿إِنَّهُۥ لَيَـُٔوسٌ كَفُورٌ﴾. ابن عاشور:١٢/١٥.\nلماذا أوثر فعل (صبروا)على فعل \"آمنوا\" في الآية الكريمة؟\nفَلَعَلَّكَ تَارِكُۢ بَعۡضَ مَا يُوحَىٰٓ إِلَيۡكَ وَضَآئِقُۢ بِهِۦ صَدۡرُكَ أَن يَقُولُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ كَنزٌ أَوۡ جَآءَ مَعَهُۥ مَلَكٌۚ\nوفي هذه الآيات إرشاد إلى أنه لا ينبغي للداعي إلى الله أن يصده اعتراض المعترضين ولا قدح القادحين؛ خصوصًا إذا كان القدح لا مُستَنَد له، ولا يقدح فيما دعا إليه. السعدي:٣٧٨.\nفي الآية فائدة لأهل الدعوة، بيِّنها.\nفَلَعَلَّكَ تَارِكُۢ بَعۡضَ مَا يُوحَىٰٓ إِلَيۡكَ وَضَآئِقُۢ بِهِۦ صَدۡرُكَ أَن يَقُولُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ كَنزٌ أَوۡ جَآءَ مَعَهُۥ مَلَكٌۚ\nإنَّما قال: (ضائق)، ولم يقل: \"ضيق\"؛ ليدل على اتساع صدره -عليه السلام-. ابن جزي:١/٣٩٢.\nلمَ قال (ضائق)؛ ولم يقل \"ضيّق\" في الآية؟"],[223,"§هود\nwords\nلاَ يُبخَسُونَلا يُنقَصُونَ شَيئًا مِن جَزَائِهِمُ الدُّنيَوِيِّ.\nمِريَةٍشَكٍّ.\nالأَشهَادُالمَلاَئِكَةُ، وَالنَّبِيُّونَ، وَالجَوَارِحُ، الَّذِينَ يَشهَدُونَ يَومَ القِيَامَةِ.\nوَيَبغُونَهَايُرِيدُونَهَا.\nعِوَجًامُعوَجَّةً، مُوَافِقَةً لِأَهوَائِهِم.\ndeeds\nاسأل الله أن يرزقك العلم والتفقه في الدين، واحرص على الابتعاد عن أكل الحرام؛ لتكون على بينة من ربك.\nاجتهد اليوم في دعوة غافل أو كافر، ولا تَضِق من عدم تجاوبه؛ فهدايته بيد الله سبحانه.\nإذا خرجت من بيتك فقل: \"اللهم إني أعوذ بك أن أضلَّ أو أُضلّ، أو أزِلَّ أو أُزلَّ، أو أظلِمَ أو أُظلمَ، أو أجهلَ أو يُجهلَ عليَّ\".\nguid\nاعمل عملًا صالحًا؛ يشهد لك به الأشهاد يوم القيامة.\nإياك والخوض في الشريعة بدون علم؛ فإنه يصل حد الكذب على الله.\nاتق ظلم نفسك بالمعاصي، أو ظلم غيرك بإضلالهم.\nrefl\nأَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِعَشۡرِ سُوَرٖ مِّثۡلِهِۦ مُفۡتَرَيَٰتٖ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ ١٣\nلما تحداهم بالإتيان بمثله في قوله: ﴿فَلۡيَأۡتُواْ بِحَدِيثٍ مِّثۡلِهِۦٓ ﴾ [الطور: ٣٤]، ثم تحداهم أن يأتوا ﴿بِعَشۡرِ سُوَرٍ مِّثۡلِهِۦ﴾ [هود:١٣]؛ فعجزوا عن ذا وذاك، ثم تحداهم أن يأتوا ﴿بِسُورَةٍ مِّثۡلِهِۦ﴾ [يونس: ٣٨]؛ فعجزوا؛ فإن الخلائق لا يمكنهم أن يأتوا بمثله، ولا بسورة مثله. ابن تيمية:٣/٥٠٩.\nبيّن مراتب تحدي الكفار بالإتيان بمثل هذا القرآن.\nقُلۡ فَأۡتُواْ بِعَشۡرِ سُوَرٖ مِّثۡلِهِۦ مُفۡتَرَيَٰتٖ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ ١٣ فَإِلَّمۡ يَسۡتَجِيبُواْ لَكُمۡ فَٱعۡلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلۡمِ ٱللَّهِ\nثـم بيّن تعالى إعجاز القرآن، وأنه لا يستطيع أحد أن يأتي بمثله، ولا ﴿بِعَشۡرِ سُوَرٍ مِّثۡلِهِۦ﴾، ولا ﴿بِسُورَةٍ مِّن مِّثۡلِهِۦ﴾ [البقرة: ٢٣]؛ لأن كلام الرب تعالى لا يشبه كلام المخلوقين، كما أن صفاته لا تشبه صفات المحدثات. ابن كثير:٢/٤٢٠.\nلمَ لا يستطيع أحدٌ أن يأتي بمثل هذا القرآن؟\nفَٱعۡلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَۖ\nمما يطلب فيه العلم ولا يكفي غلبة الظن: علم القرآن، وعلم التوحيد؛ لقوله تعالى: ﴿فَٱعۡلَمُوٓاْ أَنَّمَآ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَۖ﴾. السعدي:٣٧٨.\nما الذي يدل عليه التعبير بـ (فاعلموا )؟\nمَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُبۡخَسُونَ ١٥\nأي: كل إرادته مقصورة على الحياة الدنيا، وعلى زينتها؛ من النساء، والبنين، والقناطير المقنطرة من الذهب والفضة، والخيل المسومة، والأنعام، والحرث؛ قد صرف رغبته وسعيه وعمله في هذه الأشياء، ولم يجعل لدار القرار من إرادته شيئًا، فهذا لا يكون إلا كافرا؛ لأنه لو كان مؤمنًا لكان ما معه من الإيمان يمنعه أن تكون جميع إرادته للدار الدنيا. السعدي:٣٧٩.\nكيف تستدل على أن هذه الآية خاصة بالمشركين؟\nمَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُبۡخَسُونَ ١٥ أُوْلَٰٓئِكَ ٱلَّذِينَ لَيۡسَ لَهُمۡ فِي ٱلۡأٓخِرَةِ إِلَّا ٱلنَّارُۖ وَحَبِطَ مَا صَنَعُواْ فِيهَا وَبَٰطِلٞ مَّا كَانُواْ يَعۡمَلُونَ ١٦\nقيل: هو لأهل الرياء، وفي الخبر أنه يقال لأهل الرياء: \"صمتم، وصليتم، وتصدقتم، وجاهدتم، وقرأتم، ليقال ذلك؛ فقد قيل ذلك\"، ثم قال إن هؤلاء أول من تسعر بهم النار. رواه أبوهريرة -رضي الله عنه- ثم بكى بكاء شديدًا... أخرجه مسلم في صحيحه بمعناه. القرطبي:١١/٨٤.\nبيّن كيف يكون حال المرائين يوم القيامة.\nأَفَمَن كَانَ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّهِۦ وَيَتۡلُوهُ شَاهِدٞ مِّنۡهُ وَمِن قَبۡلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامٗا وَرَحۡمَةًۚ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۚ\nومعناه: أفمن كان على بينة من ربه كمن يريد الحياة الدنيا وزينتها، أو من كان على بينة من ربه كمن هو في الضلالة والجهالة. البغوي:٢/٣٩٢.\nهل يستوي حال من تعلق بالدنيا ومن هداه الله تعالى إلى الحق؟\nأَلَا لَعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ ١٨ ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجٗا وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ١٩\n﴿ٱلَّذِينَ يَصُدُّونَ﴾ أنفسهم وغيرهم عن الإيمان والطاعة، ﴿وَيَبۡغُونَهَا عِوَجًا﴾ أي: يعدلون بالناس عنها إلى المعاصي والشرك. القرطبي:١١/٩٢.\nما صفات الذين لعنهم الله تعالى في الآية؟"]])